// src/server/dashboard.ts — Light E-ink Paper Developer Dashboard & REST API (V2)

import { IncomingMessage, ServerResponse } from "node:http";
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { Bot } from "grammy";
import { getConfig } from "@/src/config";
import { CatalogService } from "@/src/services/catalog.service";
import { OrderService } from "@/src/services/order.service";
import { PublishingService } from "@/src/services/publishing.service";
import { CustomerService } from "@/src/services/customer.service";
import { AccountService } from "@/src/services/account.service";
import { AccountInstance, SanitizedAccountInstance, SanitizedAccountProfileItem } from "@/src/types/account";
import { SubscriptionService } from "@/src/services/subscription.service";
import { AnalyticsService } from "@/src/services/analytics.service";
import { DiscordService } from "@/src/services/discord.service";
import { ReferralService } from "@/src/services/referral.service";
import { ExpenseService } from "@/src/services/expense.service";
import { SummaryService } from "@/src/services/summary.service";
import { SupplierService } from "@/src/services/supplier.service";
import { AuditService } from "@/src/services/audit.service";
import { SettingsService } from "@/src/services/settings.service";
import { isCloudFirestore, invalidateFirestoreCache } from "@/src/services/firestore-store";
import { getFirestore, lastFirestoreError } from "@/src/db/firestore";
import { checkDbConnection, getPool } from "@/src/db/pool";
import { query } from "@/src/db/client";
import { getLogger } from "@/src/logger";
import { sanitizeUserInput } from "@/src/utils/security";
import { safeCompare, verifyTelegramWebhookSecret, extractTelegramWebhookSecret } from "@/src/server/auth";
import { TelegramDeduplicationService } from "@/src/services/telegram-dedup.service";
import { handleV2ApiRequest } from "@/src/server/api-v2";
import { getSupplierPortalHtml } from "@/src/server/supplier-ui";
import { getResellerPortalHtml } from "@/src/server/reseller-ui";
import { getAdminControlPlaneHtml } from "@/src/server/admin-ui";
import { getLandingHtml } from "@/src/server/landing-ui";
import { getLoginHtml, getSignupHtml, getResetPasswordHtml } from "@/src/server/auth-ui";
import { applySecurityHeaders, inspectWafRequest, STRICT_CSP } from "@/src/security/security-headers";
import { checkHttpRateLimit } from "@/src/services/rate-limiter.service";
import { checkLiveness, checkReadiness, checkDeepHealth } from "@/src/services/health.service";
import { metrics } from "@/src/telemetry/metrics.service";
import { captureException } from "@/src/telemetry/telemetry.service";

function getSafeLogger() {
  try {
    return getLogger();
  } catch {
    return {
      info: (...args: any[]) => {},
      warn: (...args: any[]) => {},
      error: (...args: any[]) => {},
      debug: (...args: any[]) => {},
    };
  }
}

// ── Server-Side Session Token & Authentication Utilities ────────
import {
  createSessionToken,
  verifySessionToken,
  revokeSessionToken,
  clearRevokedTokensForTest,
} from "@/src/server/legacy-session";
export {
  createSessionToken,
  verifySessionToken,
  revokeSessionToken,
  clearRevokedTokensForTest,
};

export { safeCompare, verifyTelegramWebhookSecret, extractTelegramWebhookSecret };

export function extractBearerToken(header: string | string[] | undefined): string | null {
  if (!header) return null;
  const str = Array.isArray(header) ? header[0] : header;
  if (typeof str !== "string") return null;
  const match = str.match(/^Bearer\s+(.+)$/i);
  return match ? match[1].trim() : null;
}

export function parseCookies(req: IncomingMessage): Record<string, string> {
  const list: Record<string, string> = {};
  const rawCookieHeader = req.headers.cookie;
  if (!rawCookieHeader) return list;
  const cookieHeader = Array.isArray(rawCookieHeader) ? rawCookieHeader.join("; ") : rawCookieHeader;
  if (typeof cookieHeader !== "string") return list;

  cookieHeader.split(";").forEach((cookie) => {
    const parts = cookie.split("=");
    const name = parts[0]?.trim();
    if (name) {
      const val = parts.slice(1).join("=").trim();
      try {
        list[name] = decodeURIComponent(val);
      } catch {
        list[name] = val;
      }
    }
  });

  return list;
}

export function isAllowedOrigin(req: IncomingMessage, origin?: string): boolean {
  if (!origin) return false;
  const host = req.headers.host;
  if (host) {
    if (origin === `http://${host}` || origin === `https://${host}`) {
      return true;
    }
  }

  try {
    const parsed = new URL(origin);
    const hostname = parsed.hostname.toLowerCase();
    if (hostname === "localhost" || hostname === "127.0.0.1" || hostname === "[::1]") {
      return true;
    }
  } catch {
    return false;
  }

  const appUrl = (process.env.APP_URL || "").trim();
  if (appUrl) {
    try {
      if (new URL(appUrl).origin.toLowerCase() === origin.toLowerCase()) return true;
    } catch {}
  }

  const vercelUrl = (process.env.VERCEL_URL || "").trim();
  if (vercelUrl) {
    try {
      const vOrigin = `https://${vercelUrl.replace(/^https?:\/\//, "")}`.toLowerCase();
      if (vOrigin === origin.toLowerCase()) return true;
    } catch {}
  }

  return false;
}

export function getCorsHeaders(req?: IncomingMessage): Record<string, string> {
  const headers: Record<string, string> = {
    "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, x-session-token",
  };

  const origin = req?.headers.origin;
  if (origin && req && isAllowedOrigin(req, origin)) {
    headers["Access-Control-Allow-Origin"] = origin;
    headers["Access-Control-Allow-Credentials"] = "true";
  } else if (!origin) {
    headers["Access-Control-Allow-Origin"] = "*";
  }
  return headers;
}

export function checkAuthorization(req: IncomingMessage, pathname: string): boolean {
  const bearerToken = extractBearerToken(req.headers.authorization);

  // 1. Scheduled cron jobs can authenticate using Bearer CRON_SECRET
  if (pathname.startsWith("/api/cron/")) {
    const cronSecret = (process.env.CRON_SECRET || "").trim();
    if (cronSecret && bearerToken && safeCompare(bearerToken, cronSecret)) {
      return true;
    }
  }

  // 2. Bearer token in Authorization header
  if (bearerToken) {
    if (verifySessionToken(bearerToken)) {
      return true;
    }
    const adminApiKey = (process.env.ADMIN_API_KEY || "").trim();
    if (adminApiKey && safeCompare(bearerToken, adminApiKey)) {
      return true;
    }
  }

  // 3. Custom x-session-token header
  const customHeader = req.headers["x-session-token"];
  if (customHeader) {
    const token = Array.isArray(customHeader) ? customHeader[0] : customHeader;
    if (typeof token === "string" && verifySessionToken(token.trim())) {
      return true;
    }
  }

  // 4. Session cookie xeurie_session
  const cookies = parseCookies(req);
  const sessionCookie = cookies["xeurie_session"];
  if (sessionCookie && verifySessionToken(sessionCookie)) {
    return true;
  }

  return false;
}

export function sanitizeAccountForListing(account: AccountInstance | any): SanitizedAccountInstance {
  if (!account) return account;
  const hasPassword = Boolean(account.password && String(account.password).trim().length > 0);
  const has2fa = Boolean(account.two_factor_link && String(account.two_factor_link).trim().length > 0);

  let sanitizedProfiles: SanitizedAccountProfileItem[] | null = null;
  const mapProfile = (p: any): SanitizedAccountProfileItem => {
    if (typeof p === "string") {
      return {
        name: p,
        has_pin: false,
        pin: null,
      };
    }
    const hasPin = Boolean(p && p.pin !== undefined && p.pin !== null && String(p.pin).trim().length > 0);
    return {
      ...(typeof p === "object" && p !== null ? p : {}),
      name: p && p.name ? String(p.name) : "Profile",
      has_pin: hasPin,
      pin: hasPin ? "••••" : null,
    };
  };

  if (Array.isArray(account.profiles)) {
    sanitizedProfiles = account.profiles.map(mapProfile);
  } else if (typeof account.profiles === "string") {
    try {
      const parsed = JSON.parse(account.profiles);
      if (Array.isArray(parsed)) {
        sanitizedProfiles = parsed.map(mapProfile);
      }
    } catch {
      sanitizedProfiles = null;
    }
  }

  const {
    password: _p,
    two_factor_link: _2fa,
    profiles: _profs,
    ...rest
  } = account;

  return {
    ...rest,
    has_password: hasPassword,
    has_2fa: has2fa,
    password: null,
    two_factor_link: null,
    profiles: sanitizedProfiles,
  };
}

function sendJson(res: ServerResponse, status: number, data: any, req?: IncomingMessage): void {
  applySecurityHeaders(res);
  res.writeHead(status, {
    "Content-Type": "application/json",
    ...getCorsHeaders(req),
  });
  res.end(JSON.stringify(data));
}

async function parseBody(req: IncomingMessage): Promise<any> {
  if ((req as any).body) {
    if (typeof (req as any).body === "string") {
      try {
        return JSON.parse((req as any).body);
      } catch {
        return {};
      }
    }
    return (req as any).body;
  }

  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => (body += chunk));
    req.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (err) {
        reject(err);
      }
    });
    req.on("error", reject);
  });
}

export function handleDashboardRequest(req: IncomingMessage, res: ServerResponse, bot: Bot): boolean {
  const startTime = Date.now();
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const pathname = url.pathname;
  const method = req.method || "GET";

  // Wrap res.end to record HTTP metrics
  if (typeof res?.end === "function" && !(res as any).__metricsWrapped) {
    (res as any).__metricsWrapped = true;
    const origEnd = res.end;
    res.end = function (...args: any[]) {
      try {
        const durationMs = Date.now() - startTime;
        const statusCode = (res as any).statusCode || (res as any)._statusCode || 200;
        metrics.recordHttpRequest({
          method,
          route: pathname,
          statusCode,
          durationMs,
        });
      } catch {
        // Safe metrics recording
      }
      return (origEnd as any).apply(this, args);
    };
  }

  if (method === "OPTIONS") {
    res.writeHead(204, getCorsHeaders(req));
    res.end();
    return true;
  }

  // WAF Request Inspection (Path Traversal, Null-byte, CRLF host)
  const wafCheck = inspectWafRequest(req);
  if (!wafCheck.allowed) {
    applySecurityHeaders(res);
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: `Bad Request: ${wafCheck.reason}` }));
    return true;
  }

  // V2 Multi-Role REST API Router (Admin/Supplier/Reseller/Auth)
  if (pathname.startsWith("/api/v2/")) {
    handleV2ApiRequest(req, res).catch((err) => {
      captureException(err, { pathname, method });
      getSafeLogger().error({ err, pathname, method }, "Unhandled error in v2 API request handler");
      if (!res.headersSent) {
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "Internal server error" }));
      }
    });
    return true;
  }

  // 0. Telegram Webhook Updates Receiver (Public Webhook)
  if (pathname === "/api/telegram" && method === "POST") {
    const auth = verifyTelegramWebhookSecret(req);
    if (!auth.valid) {
      sendJson(res, auth.status || 403, { ok: false, error: auth.message }, req);
      return true;
    }

    const bodyPromise = parseBody(req);
    checkHttpRateLimit(req, res, "webhook", "tg").then(async (rateOk) => {
      if (!rateOk) return;

      try {
        const body = await bodyPromise;
        if (body && typeof body === "object" && "update_id" in body) {
          const acquired = await TelegramDeduplicationService.acquireOrSkip(body.update_id);
          if (!acquired) {
            getSafeLogger().info({ update_id: body.update_id }, "Duplicate Telegram update received; returning 200 OK");
            sendJson(res, 200, { ok: true, duplicate: true }, req);
            return;
          }
          if (bot && typeof bot.handleUpdate === "function") {
            await bot.handleUpdate(body);
          }
        }
        sendJson(res, 200, { ok: true }, req);
      } catch (err: any) {
        sendJson(res, 200, { ok: false, error: err?.message || "Error" }, req);
      }
    });
    return true;
  }

  if (pathname === "/api/telegram" && method === "GET") {
    sendJson(res, 200, { ok: true, status: "Telegram webhook receiver is active" }, req);
    return true;
  }

  // 1a. Liveness Probe (Instant Container / Heartbeat Ping)
  if (pathname === "/health/live" || pathname === "/api/health/live") {
    sendJson(res, 200, checkLiveness(), req);
    return true;
