          : '<span style="color:var(--ink-muted); font-size:11px;">Verified</span>';

        const commission = s.commission_rate_bps !== undefined ? ((Number(s.commission_rate_bps) / 100).toFixed(1) + '%') : '10.0%';
        const contact = s.telegram_username ? ('@' + escapeHtml(s.telegram_username.replace(/^@/, ''))) : (escapeHtml(s.contact_info || '-'));

