    let currentAssignOrderId = null;
    function openAssignModal(orderId) {
      currentAssignOrderId = orderId;
      const order = (globalData.orders || []).find(o => o.id === orderId);
      const pSnap = order ? safeJson(order.product_snapshot) : {};
      const productId = order ? (order.product_id || pSnap.id || null) : null;
      const productName = order ? (pSnap.name || order.product_name || 'Product') : 'Product';
      const orderCode = order ? (order.code || order.id) : orderId;

      document.getElementById('assign-order-desc').innerHTML = 'Order: <code>' + escapeHtml(orderCode) + '</code> — Product: <strong>' + escapeHtml(productName) + '</strong>';

      const available = (globalData.accounts || []).filter(a => {
        if (productId && Number(a.product_id) !== Number(productId)) return false;
        if (a.status === 'AVAILABLE') return true;
        if (Array.isArray(a.profiles) && a.profiles.length > 0) {
          return a.profiles.some(p => p.status !== 'ASSIGNED');
        }
        return false;
      });

      const select = document.getElementById('assign-account-select');
      select.innerHTML = available.length === 0 
        ? '<option value="">No available accounts in pool</option>' 
        : available.map(a => {
            const label = a.email || a.label;
            const pwdTag = (a.has_password || a.password) ? ' (🔑 Password set)' : '';
            let profTag = '';
            if (Array.isArray(a.profiles) && a.profiles.length > 0) {
              const unsold = a.profiles.filter(p => p.status !== 'ASSIGNED').length;
              profTag = ' (' + unsold + '/' + a.profiles.length + ' profiles available)';
            }
            const twoFaTag = (a.has_2fa || a.two_factor_link) ? ' [2FA]' : '';
            return '<option value="' + a.id + '">' + escapeHtml(label) + pwdTag + profTag + twoFaTag + '</option>';
          }).join('');

      onAssignAccountSelectChange();
      openModal('assignModal');
    }

    function onAssignAccountSelectChange() {
      const select = document.getElementById('assign-account-select');
      const group = document.getElementById('assign-profile-group');
      const profSelect = document.getElementById('assign-profile-select');
      const countSpan = document.getElementById('assign-profile-count');
      if (!select || !group || !profSelect) return;

      const accountId = Number(select.value);
      const acc = (globalData.accounts || []).find(a => a.id === accountId);

      if (!acc || !Array.isArray(acc.profiles) || acc.profiles.length === 0) {
        group.style.display = 'none';
        profSelect.innerHTML = '';
        return;
      }

      group.style.display = 'block';
      const unsoldProfiles = acc.profiles.filter(p => p.status !== 'ASSIGNED');
      const soldProfiles = acc.profiles.filter(p => p.status === 'ASSIGNED');

      if (countSpan) {
        countSpan.innerText = unsoldProfiles.length + '/' + acc.profiles.length + ' available';
      }

      let optionsHtml = '';
      if (soldProfiles.length > 0) {
        optionsHtml += '<option value="" disabled>-- Whole Account (Unavailable: ' + soldProfiles.length + ' profile(s) already sold) --</option>';
      } else {
        optionsHtml += '<option value="">-- Whole Account (All Profiles / Solo) --</option>';
      }

      acc.profiles.forEach(p => {
        const isSold = p.status === 'ASSIGNED';
        const pinText = p.pin ? ' (PIN: ' + p.pin + ')' : '';
        const soldText = isSold ? ' — 🔴 Sold' + (p.assigned_order_code ? ' (' + escapeHtml(p.assigned_order_code) + ')' : '') : ' — 🟢 Available';
        const disabled = isSold ? ' disabled' : '';
        optionsHtml += '<option value="' + escapeHtml(p.name).replace(/"/g, '&quot;') + '"' + disabled + '>' +
          '👤 ' + escapeHtml(p.name) + escapeHtml(pinText) + soldText +
        '</option>';
      });

      profSelect.innerHTML = optionsHtml;

      // If whole account is disabled, pre-select the first available profile
      if (soldProfiles.length > 0 && unsoldProfiles.length > 0) {
        profSelect.value = unsoldProfiles[0].name;
      }
    }

