    function getProfilesFromContainer(containerId) {
      const container = document.getElementById(containerId);
      if (!container) return [];
      const rows = container.querySelectorAll('.prof-row');
      const list = [];
      rows.forEach(r => {
        const name = (r.querySelector('.prof-name')?.value || '').trim();
        const pin = (r.querySelector('.prof-pin')?.value || '').trim();
        if (name || pin) {
          let meta = {};
          if (r.dataset && r.dataset.meta) {
            try { meta = JSON.parse(r.dataset.meta); } catch(e) {}
          }
          list.push({
            ...meta,
            name: name || 'Profile',
            pin: pin || null
          });
        }
      });
      return list;
    }

