      try {
        let link = a.two_factor_link;
        if (!link) {
          const creds = await fetchAccountCredentials(id);
          link = creds.two_factor_link || '';
        }
        if (!link) {
          alert('No 2FA link/key configured for this account.');
          return;
        }
        const isUrl = /^https?:\/\//i.test(link);
        if (isUrl) {
          const win = window.open(link, '_blank', 'noopener,noreferrer');
          if (!win || win.closed || typeof win.closed === 'undefined') {
            copyToClipboard(link);
            alert('Popup was blocked by browser. 2FA link has been copied to your clipboard:\\n' + link);
          }
        } else {
          copyToClipboard(link);
          const win = window.open('https://2fa.live', '_blank', 'noopener,noreferrer');
          if (!win || win.closed || typeof win.closed === 'undefined') {
            alert('2FA Secret Key copied to clipboard! (Visit https://2fa.live to generate your 2FA OTP code)');
          }
        }
      } catch (err) {
        alert('Could not retrieve 2FA link: ' + err.message);
      }
    }

