      const count = checkedBoxes.length;
      const countSpan = document.getElementById('selected-orders-count');
      const btn = document.getElementById('btn-bulk-delete-orders');
      if (countSpan) countSpan.innerText = count;
      if (btn) btn.style.display = count > 0 ? 'inline-flex' : 'none';

      const allBoxes = document.querySelectorAll('.order-checkbox');
      const masterCheckbox = document.getElementById('th-select-all-orders');
      if (masterCheckbox && allBoxes.length > 0) {
        masterCheckbox.checked = (checkedBoxes.length === allBoxes.length);
