    async function bulkDeleteSelectedOrders() {
      const checkedBoxes = document.querySelectorAll('.order-checkbox:checked');
      const ids = Array.from(checkedBoxes).map(cb => cb.value);
      if (ids.length === 0) return;

      if (!confirm('Are you sure you want to permanently delete ' + ids.length + ' selected order(s)?')) {
        return;
      }

      const res = await fetch('/api/orders/bulk-delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids })
      }).then(r => r.json()).catch(() => ({}));

      if (res.success) {
        const masterCheckbox = document.getElementById('th-select-all-orders');
        if (masterCheckbox) masterCheckbox.checked = false;
        const btn = document.getElementById('btn-bulk-delete-orders');
        if (btn) btn.style.display = 'none';
        loadAll();
      } else {
        alert('Failed to delete orders: ' + (res.error || 'Unknown error'));
      }
    }

    async function promptClearAllOrders() {
      const scope = prompt('Type ALL to delete all orders, or PENDING to delete only pending orders:');
      if (!scope) return;
      const upper = scope.toUpperCase().trim();
      if (upper !== 'ALL' && upper !== 'PENDING') {
        alert('Cancelled. You must type either ALL or PENDING.');
        return;
      }

      if (!confirm('Are you sure you want to permanently delete ' + upper + ' orders?')) return;

      const res = await fetch('/api/orders/clear-all', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ scope: upper })
      }).then(r => r.json()).catch(() => ({}));

      if (res.success) {
        alert('Deleted ' + (res.count || 0) + ' orders.');
        loadAll();
      } else {
        alert('Failed to clear orders: ' + (res.error || 'Unknown error'));
      }
    }

    async function deleteCustomer(id) {
      if (!confirm('Are you sure you want to delete this customer profile?')) return;
      await fetch('/api/customers/' + id, { method: 'DELETE' });
      loadAll();
    }

    async function saveNewCustomer() {
      const username = document.getElementById('cust-username').value.trim();
      const displayName = document.getElementById('cust-name').value.trim();
      const telegramId = document.getElementById('cust-tg-id').value.trim();
      const notes = document.getElementById('cust-notes').value.trim();

      if (!username && !displayName && !telegramId) {
        alert('Please enter at least a username, name, or Telegram ID.');
        return;
      }

      await fetch('/api/customers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, displayName, telegramId, notes })
      });
      closeModal('addCustomerModal');
      loadAll();
    }

    // Manual Order Form Helpers
    function populateManualOrderModal() {
      const custSelect = document.getElementById('ord-customer-select');
      const prodSelect = document.getElementById('ord-product-select');

      custSelect.innerHTML = '<option value="">-- Type New Customer Below --</option>' +
        (globalData.customers || []).map(c => '<option value="' + escapeHtml(c.telegram_id) + '">' + escapeHtml(c.display_name || '') + ' (@' + escapeHtml(c.username || c.telegram_id) + ')</option>').join('');

      prodSelect.innerHTML = (globalData.products || []).map(p => '<option value="' + p.id + '">' + escapeHtml(p.name) + '</option>').join('');

      onOrderProductSelectChange();
    }

    function onOrderCustomerSelectChange() {
      const val = document.getElementById('ord-customer-select').value;
      const newCustFields = document.getElementById('ord-new-cust-fields');
      newCustFields.style.display = val ? 'none' : 'flex';
    }

    function onOrderProductSelectChange() {
      const pId = Number(document.getElementById('ord-product-select').value);
      const prod = (globalData.products || []).find(p => p.id === pId);
      const varSelect = document.getElementById('ord-variant-select');

      if (!prod || !prod.variants || prod.variants.length === 0) {
        varSelect.innerHTML = '<option value="">No active plans for this product</option>';
        document.getElementById('ord-price').value = '';
        document.getElementById('ord-cost').value = '';
        recalcOrderTotal();
        return;
      }

      varSelect.innerHTML = prod.variants.map(v => '<option value="' + v.id + '" data-price="' + v.price + '" data-cost="' + (v.cost||0) + '">' + escapeHtml(v.name) + ' (₱' + Number(v.price).toFixed(0) + ')</option>').join('');
      onOrderVariantSelectChange();
    }

    function onOrderVariantSelectChange() {
      const varSelect = document.getElementById('ord-variant-select');
      const selected = varSelect.options[varSelect.selectedIndex];
      if (selected) {
        document.getElementById('ord-price').value = selected.getAttribute('data-price') || 0;
        document.getElementById('ord-cost').value = selected.getAttribute('data-cost') || 0;
      }
      recalcOrderTotal();
    }

    function recalcOrderTotal() {
      const qty = Number(document.getElementById('ord-qty').value) || 1;
      const price = Number(document.getElementById('ord-price').value) || 0;
      const total = qty * price;
      document.getElementById('ord-total-calc').innerText = '₱' + total.toFixed(2);
    }

    async function saveManualOrder() {
      const customerId = document.getElementById('ord-customer-select').value;
      const customerUsername = document.getElementById('ord-new-cust-user').value.trim();
      const customerName = document.getElementById('ord-new-cust-name').value.trim();
      const productId = Number(document.getElementById('ord-product-select').value);
      const variantId = Number(document.getElementById('ord-variant-select').value);
      const quantity = Number(document.getElementById('ord-qty').value) || 1;
      const customPrice = Number(document.getElementById('ord-price').value);
      const customCost = Number(document.getElementById('ord-cost').value) || 0;
      const state = document.getElementById('ord-state').value;

      if (!customerId && !customerUsername && !customerName) {
        alert('Please select an existing customer or enter new customer details.');
        return;
      }
      if (!productId || !variantId || isNaN(customPrice)) {
        alert('Please select a valid product and plan.');
        return;
      }

      const res = await fetch('/api/orders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customerId,
          customerUsername,
          customerName,
          productId,
          variantId,
          quantity,
          customPrice,
          customCost,
          state
        })
      }).then(r => r.json());

      if (res.order) {
        alert('✅ Order ' + res.order.code + ' recorded successfully!');
        closeModal('addOrderModal');
        loadAll();
      } else {
        alert('❌ Error creating order: ' + (res.error || 'Unknown error'));
      }
    }

    checkAuth();
    // Staggered polling: fast orders (15s), medium subs (60s), slow bootstrap (5m)
    setInterval(async () => {
      if (localStorage.getItem('xeurie_auth') !== 'true' && !localStorage.getItem('xeurie_token')) return;
      try {
        const r = await fetch('/api/orders').then(res => res.json()).catch(() => null);
        if (r && r.orders) {
          globalData.orders = r.orders;
          renderOrders(globalData.orders);
          document.getElementById('badge-orders-nav').innerText = globalData.orders.length;
        }
      } catch {}
    }, 15000);

    setInterval(async () => {
      if (localStorage.getItem('xeurie_auth') !== 'true' && !localStorage.getItem('xeurie_token')) return;
      try {
        const r = await fetch('/api/subscriptions').then(res => res.json()).catch(() => null);
        if (r && r.subscriptions) {
          globalData.subscriptions = r.subscriptions;
          renderSubscriptions(globalData.subscriptions);
          document.getElementById('badge-subs-nav').innerText = globalData.subscriptions.length;
        }
      } catch {}
    }, 60000);

    setInterval(() => {
      if (localStorage.getItem('xeurie_auth') === 'true' && localStorage.getItem('xeurie_token')) {
        loadAll();
      }
    }, 300000);
  </script>
</body>
</html>`;
