function exportOrdersCsv() {
  const orders = (typeof globalData !== 'undefined' && Array.isArray(globalData.orders)) ? globalData.orders : [];
  if (orders.length === 0) { alert('No orders to export.'); return; }
  const csvCell = (v) => {
    let s = (v === null || v === undefined) ? '' : String(v);
    // Neutralise spreadsheet formula injection
    if (/^[=+@\t\r-]/.test(s) && isNaN(Number(s))) s = "'" + s;
    return '"' + s.split('"').join('""') + '"';
  };
  const header = ['Code', 'Customer', 'Product', 'Plan', 'Quantity', 'Total', 'Profit', 'State', 'Created'];
  const rows = orders.map(o => {
    const pSnap = safeJson(o.product_snapshot);
    const vSnap = safeJson(o.variant_snapshot);
    return [
      o.code || o.id,
      o.customer_username ? '@' + o.customer_username : o.customer_id,
      pSnap.name || o.product_name || '',
      vSnap.name || o.variant_name || '',
      o.quantity || 1,
      Number(o.total || 0).toFixed(2),
      Number(o.gross_profit_snapshot || 0).toFixed(2),
      o.state || '',
      o.created_at || ''
    ].map(csvCell).join(',');
  });
  const csv = '﻿' + [header.map(csvCell).join(',')].concat(rows).join(String.fromCharCode(13, 10));
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'orders-' + new Date().toISOString().slice(0, 10) + '.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

