      "Strict-Transport-Security": "max-age=31536000; includeSubDomains; preload",
      "Content-Security-Policy": STRICT_CSP,
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    });
    res.end(method === "HEAD" ? undefined : getResetPasswordHtml({ error }));
    return true;
  }

  // 2. Modern SaaS Admin Command Center UI (Task T25 / Phase R8 — Lock Q Private Control Plane)
  if (
    pathname === "/admin/control-plane" ||
    pathname === "/control-plane" ||
    pathname === "/admin/v2" ||
    (pathname === "/admin" && url.searchParams.get("v") === "2")
  ) {
    res.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-cache",
      "Strict-Transport-Security": "max-age=31536000; includeSubDomains; preload",
      "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; img-src 'self' data: https:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    });
    res.end(getAdminControlPlaneHtml());
    return true;
  }

  // 2b. Admin UI (Deployments & Commerce Console)
  if (pathname === "/admin" || pathname === "/dashboard") {
    res.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-cache",
      "Strict-Transport-Security": "max-age=31536000; includeSubDomains; preload",
      "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; img-src 'self' data: https:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    });
    res.end(getDashboardHtml());
    return true;
  }

  // 2b. Supplier Web Portal UI (Phase 5 — Task 5.1)
  if (pathname === "/supplier" || pathname === "/supplier/" || pathname.startsWith("/supplier/")) {
    res.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-cache",
      "Strict-Transport-Security": "max-age=31536000; includeSubDomains; preload",
      "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    });
    res.end(getSupplierPortalHtml());
    return true;
  }

  // 2c. Reseller Web Portal UI (Phase 6 — Task 6.1)
  if (pathname === "/reseller" || pathname === "/reseller/" || pathname.startsWith("/reseller/")) {
    res.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-cache",
      "Strict-Transport-Security": "max-age=31536000; includeSubDomains; preload",
      "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    });
    res.end(getResellerPortalHtml());
    return true;
  }

  // 2b. REST API — Owner Login Authentication (Public Auth Endpoint, Secure Session Issuance)
  if (pathname === "/api/auth/login" && method === "POST") {
    const bodyPromise = parseBody(req);
    checkHttpRateLimit(req, res, "auth", "login").then(async (rateOk) => {
      if (!rateOk) return;

      try {
        const body = await bodyPromise;
        const pin = String(body.pin || "").trim();
        let adminPass = process.env.ADMIN_PASSWORD || "";
        if (!adminPass) {
          try {
            adminPass = (getConfig() as any).ADMIN_PASSWORD || "";
          } catch {}
        }
        adminPass = adminPass.replace(/^["']|["']$/g, "").trim();

        const isValidPass = adminPass.length > 0 && safeCompare(pin, adminPass);

        if (pin.length > 0 && isValidPass) {
          const isProdOrVercel = process.env.NODE_ENV === "production" || process.env.VERCEL === "1";
          const token = createSessionToken();
          const cookieFlags = `Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000${isProdOrVercel ? "; Secure" : ""}`;
          let setCookieHeader: string | string[] = `xeurie_session=${token}; ${cookieFlags}`;

          try {
            const { createSessionToken: createV2Token } = await import("@/src/auth/service");
            const v2Token = createV2Token({
              userId: "00000000-0000-0000-0000-000000000001",
              orgId: "00000000-0000-0000-0000-000000000000",
              role: "super_admin",
              email: "euriepaulino92@gmail.com",
            });
            setCookieHeader = [
              `xeurie_session=${token}; ${cookieFlags}`,
              `xeurie_session_v2=${v2Token}; ${cookieFlags}`
            ];
          } catch {}

          res.writeHead(200, {
            "Content-Type": "application/json",
            "Set-Cookie": setCookieHeader,
            ...getCorsHeaders(req),
          });
          res.end(JSON.stringify({ success: true, token, message: "Authenticated successfully" }));
        } else {
          sendJson(res, 401, { error: "Invalid Owner PIN / Password" }, req);
        }
      } catch (err: any) {
        sendJson(res, 400, { error: err.message }, req);
      }
    });
    return true;
  }

  // 2c. REST API — Owner Logout (Clears session cookie & revokes token)
  if (pathname === "/api/auth/logout" && (method === "POST" || method === "GET")) {
    const cookies = parseCookies(req);
    const cookieToken = cookies["xeurie_session"] || cookies["xeurie_session_v2"];
    if (cookieToken) revokeSessionToken(cookieToken);

    const bearerToken = extractBearerToken(req.headers.authorization);
    if (bearerToken) revokeSessionToken(bearerToken);

    const xSessionToken = req.headers["x-session-token"];
    if (xSessionToken) {
      const token = Array.isArray(xSessionToken) ? xSessionToken[0] : xSessionToken;
      if (typeof token === "string" && token.trim()) {
        revokeSessionToken(token.trim());
      }
    }

    const isProdOrVercel = process.env.NODE_ENV === "production" || process.env.VERCEL === "1";
    const wantsJson = req.headers.accept?.includes("application/json") && method === "POST";

    const cookieHeaders = [
      `xeurie_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${isProdOrVercel ? "; Secure" : ""}`,
      `xeurie_session_v2=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${isProdOrVercel ? "; Secure" : ""}`,
      `admin_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${isProdOrVercel ? "; Secure" : ""}`,
      `sb-access-token=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${isProdOrVercel ? "; Secure" : ""}`,
      `sb-refresh-token=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${isProdOrVercel ? "; Secure" : ""}`,
    ];

    if (wantsJson) {
      res.writeHead(200, {
        "Content-Type": "application/json",
        "Set-Cookie": cookieHeaders,
        ...getCorsHeaders(req),
      });
      res.end(JSON.stringify({ success: true, message: "Logged out" }));
      return true;
    }

    res.writeHead(303, {
      Location: "/login?logged_out=true",
      "Set-Cookie": cookieHeaders,
      ...getCorsHeaders(req),
    });
    res.end();
    return true;
  }

  if (pathname.startsWith("/api/auth/")) {
    sendJson(res, 405, { error: "Method Not Allowed" }, req);
    return true;
  }

  // 2d. Server-Side Authentication Middleware for all protected /api/* endpoints
  if (pathname.startsWith("/api/")) {
    if (!checkAuthorization(req, pathname)) {
      sendJson(res, 401, {
        error: "Unauthorized",
        message: "Authentication required. Please provide a valid session cookie or authorization header.",
      }, req);
      return true;
    }
  }

  // 2e. REST API — Consolidated Dashboard Bootstrap (reduces concurrent requests to 1)
  if (pathname === "/api/dashboard/bootstrap" && method === "GET") {
    (async () => {
      try {
        const [analytics, products, orders, subscriptions, accounts, customers, settings, restocks, expenses, dbSuppliers, dbResellers] = await Promise.all([
          AnalyticsService.getDashboardMetrics().catch(() => ({})),
          CatalogService.getCatalog(false).catch(() => []),
          OrderService.listOrders({ limit: 100 }).catch(() => []),
          SubscriptionService.listSubscriptions({}).catch(() => []),
          AccountService.listAccounts({}).catch(() => []),
          CustomerService.listCustomers().catch(() => []),
          SettingsService.getAllSettings().catch(() => ({})),
          SupplierService.listRestockHistory(50).catch(() => []),
          ExpenseService.listExpenses().catch(() => []),
          query(`
            SELECT o.id, o.name, o.type, o.created_at,
                   u.email, u.display_name, u.status, u.telegram_id, u.telegram_username,
                   sp.contact_info, sp.payout_address, sp.commission_rate_bps, sp.is_verified
            FROM organizations o
            LEFT JOIN app_users u ON u.organization_id = o.id AND u.role = 'supplier'
            LEFT JOIN supplier_profiles sp ON sp.organization_id = o.id
            WHERE o.type = 'SUPPLIER_ORG'
            ORDER BY o.created_at DESC
          `).catch(() => []),
          query(`
            SELECT o.id, o.name, o.type, o.created_at,
                   u.email, u.display_name, u.status, u.telegram_id, u.telegram_username,
                   rp.tier, rp.credit_balance, rp.markup_percentage, rp.credit_limit
            FROM organizations o
            LEFT JOIN app_users u ON u.organization_id = o.id AND u.role = 'reseller'
            LEFT JOIN reseller_profiles rp ON rp.organization_id = o.id
            WHERE o.type = 'RESELLER_ORG'
            ORDER BY o.created_at DESC
          `).catch(() => []),
        ]);

        const legacySuppliers = await SupplierService.listSuppliers().catch(() => []);
        const mergedSuppliers = [
          ...(Array.isArray(dbSuppliers) ? dbSuppliers : []),
          ...(Array.isArray(legacySuppliers) ? legacySuppliers.map((s: any) => ({
            id: s.id,
            name: s.name,
            display_name: s.name,
            contact_info: s.contact,
            telegram_username: s.contact,
            status: 'ACTIVE',
            is_verified: true,
            commission_rate_bps: 1000,
            created_at: s.created_at || new Date().toISOString(),
          })) : [])
        ];

        sendJson(res, 200, {
          analytics,
          products,
          orders,
          subscriptions,
          accounts: (Array.isArray(accounts) ? accounts : []).map(sanitizeAccountForListing),
          customers,
          settings,
          restocks,
          expenses,
          suppliers: mergedSuppliers,
          resellers: Array.isArray(dbResellers) ? dbResellers : [],
        }, req);
      } catch (err: any) {
        sendJson(res, 500, { error: err.message }, req);
      }
    })();
    return true;
  }

  // 3. REST API — Analytics & Metrics
  if (pathname === "/api/analytics" && method === "GET") {
    AnalyticsService.getDashboardMetrics()
      .then((metrics) => sendJson(res, 200, metrics))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 4. REST API — Catalog List
  if (pathname === "/api/catalog" && method === "GET") {
    CatalogService.getCatalog(false)
      .then((products) => sendJson(res, 200, { products }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 5. REST API — Create Product
  if (pathname === "/api/products" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const name = sanitizeUserInput(String(body.name || ""), 100);
        if (!name) {
          return sendJson(res, 400, { error: "Product name is required" }, req);
        }
        const product = await CatalogService.createProduct({
          name,
          category: sanitizeUserInput(String(body.category || "General"), 50),
          status: body.status || "AVAILABLE",
          stock: body.stock !== undefined && body.stock !== "" ? Number(body.stock) : null,
          visibility: "VISIBLE",
        });

        if (Array.isArray(body.variants) && body.variants.length > 0) {
          for (const v of body.variants) {
            if (v.name && v.price !== undefined && !isNaN(Number(v.price))) {
              await CatalogService.addVariant({
                product_id: product.id,
                name: sanitizeUserInput(String(v.name), 100),
                price: Number(v.price),
                cost: v.cost ? Number(v.cost) : 0,
              });
            }
          }
        } else if (body.variantName && body.price !== undefined) {
          await CatalogService.addVariant({
            product_id: product.id,
            name: sanitizeUserInput(String(body.variantName), 100),
            price: Number(body.price),
            cost: body.cost ? Number(body.cost) : 0,
          });
        }

        PublishingService.triggerAutoSync(bot);
        await AuditService.log({ action: "CREATE_PRODUCT", entity: "product", entityId: product.id, details: `Created product ${product.name}` });
        sendJson(res, 201, { product });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 6. REST API — Update Stock
  const stockMatch = pathname.match(/^\/api\/products\/(\d+)\/stock$/);
  if (stockMatch && method === "PATCH") {
    const id = Number(stockMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const stock = body.stock === null || body.stock === "" ? null : Number(body.stock);
        const updated = await CatalogService.updateProduct(id, { stock });
        PublishingService.triggerAutoSync(bot);
        await AuditService.log({ action: "UPDATE_STOCK", entity: "product", entityId: id, details: `Stock updated to ${stock === null ? 'unlimited' : stock}` });
        sendJson(res, 200, { product: updated });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 6b. REST API — Update Product Status
  const statusMatch = pathname.match(/^\/api\/products\/(\d+)\/status$/);
  if (statusMatch && method === "PATCH") {
    const id = Number(statusMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const status = body.status;
        if (!["AVAILABLE", "LIMITED", "SOLD_OUT", "PRE_ORDER"].includes(status)) {
          return sendJson(res, 400, { error: "Invalid product status" });
        }
        const updated = await CatalogService.updateProduct(id, { status });
        PublishingService.triggerAutoSync(bot);
        await AuditService.log({ action: "UPDATE_STATUS", entity: "product", entityId: id, details: `Status updated to ${status}` });
        sendJson(res, 200, { product: updated });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 7. REST API — Toggle Visibility
  const visMatch = pathname.match(/^\/api\/products\/(\d+)\/visibility$/);
  if (visMatch && method === "PATCH") {
    const id = Number(visMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const updated = await CatalogService.updateProduct(id, { visibility: body.visibility });
        PublishingService.triggerAutoSync(bot);
        sendJson(res, 200, { product: updated });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 7b. REST API — Update Product Details
