    parseBody(req)
      .then(async (body) => {
        const supplierOrgId = String(body.supplierOrgId || "").trim();
        const decision = body.decision === "REJECT" ? "REJECT" : "APPROVE";
        if (!supplierOrgId) {
          return sendJson(res, 400, { error: "supplierOrgId is required" }, req);
        }
        const { reviewSupplierOnboardingApplication } = await import("@/src/admin/admin.service");
        const result = await reviewSupplierOnboardingApplication(
          { isInternalAdmin: true, user: { role: "super_admin" } } as any,
          {
            supplierOrgId,
            decision,
            commissionRateBps: body.commissionRateBps !== undefined ? Number(body.commissionRateBps) : undefined,
            notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : undefined,
          }
        );
        await AuditService.log({
          action: "REVIEW_SUPPLIER",
          entity: "supplier",
          entityId: supplierOrgId,
          details: `Supplier application ${decision.toLowerCase()}d for org ${supplierOrgId}`,
        });
        sendJson(res, 200, result, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }, req));
    return true;
  }

  // 23c. REST API — Credit Reseller Wallet
  if (pathname === "/api/resellers/credit" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const resellerId = String(body.resellerOrgId || body.resellerId || "").trim();
        const amount = Number(body.amount);
        if (!resellerId || isNaN(amount) || amount <= 0) {
          return sendJson(res, 400, { error: "Valid resellerOrgId and positive amount are required" }, req);
        }
        const { creditResellerWallet } = await import("@/src/admin/admin.service");
        const result = await creditResellerWallet(
          { isInternalAdmin: true, user: { role: "super_admin" } } as any,
          {
            resellerId,
            amount,
            referenceId: String(body.referenceId || ("admin-credit-" + Date.now())),
            notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : "Manual admin credit",
          }
        );
        await AuditService.log({
          action: "CREDIT_RESELLER",
          entity: "reseller",
          entityId: resellerId,
          details: `Credited ₱${amount.toFixed(2)} to reseller org ${resellerId}`,
        });
        sendJson(res, 200, { success: true, ...result }, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }, req));
    return true;
  }

  // 24. REST API — Audit Logs
  if (pathname === "/api/audit-logs" && method === "GET") {
    AuditService.list()
      .then((logs) => sendJson(res, 200, { logs }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 25. REST API — Demand & Restock Waitlist Notification
  if (pathname === "/api/demand" && method === "GET") {
    (async () => {
      let requests: any[] = [];
      let waitlists: any[] = [];
      if (isCloudFirestore()) {
        const db = getFirestore();
        const reqSnap = await db.collection("product_requests").orderBy("created_at", "desc").limit(50).get();
        requests = reqSnap.docs.map((d) => ({ id: d.id, ...d.data() }));

        const waitSnap = await db.collection("waitlist").orderBy("created_at", "desc").limit(100).get();
        waitlists = waitSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      }
      sendJson(res, 200, { requests, waitlists });
    })().catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  const notifyWaitlistMatch = pathname.match(/^\/api\/waitlist\/(\d+)\/notify$/);
  if (notifyWaitlistMatch && method === "POST") {
    const productId = Number(notifyWaitlistMatch[1]);
    (async () => {
      if (isCloudFirestore()) {
        const db = getFirestore();
        const prodDoc = await db.collection("products").doc(String(productId)).get();
        const prodData = prodDoc.data() || {};
        const pName = prodData.name || "Product";

        const waitSnap = await db.collection("waitlist").where("product_id", "==", productId).where("status", "==", "WAITING").get();
        let notifiedCount = 0;

        for (const doc of waitSnap.docs) {
          const wData = doc.data();
          try {
            await bot.api.sendMessage(
              wData.customer_id,
              `🎉 <b>GOOD NEWS! BACK IN STOCK!</b>\n\n<b>${pName}</b> is now available! Order now before slots run out:`,
              {
                parse_mode: "HTML",
                reply_markup: {
                  inline_keyboard: [[{ text: "🛒 Order " + pName, callback_data: `customer:order:${productId}` }]],
                },
              }
            );
            await doc.ref.update({ status: "NOTIFIED", notified_at: new Date().toISOString() });
            notifiedCount++;
          } catch {}
        }
        sendJson(res, 200, { success: true, notifiedCount });
      } else {
        sendJson(res, 200, { success: true, notifiedCount: 0 });
      }
    })().catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 26. REST API — Customer Expiration Reminders Trigger
  if (pathname === "/api/cron/expiration-reminders" && method === "POST") {
    SummaryService.sendCustomerExpirationReminders(bot)
      .then((result) => sendJson(res, 200, { success: true, ...result }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 27. REST API — Danger Zone: Clear Test Orders
  if (pathname === "/api/danger/clear-test-orders" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        if (body.confirmation !== "CONFIRM_DELETE_TEST_ORDERS") {
          sendJson(res, 400, { error: "Incorrect confirmation string. Must type CONFIRM_DELETE_TEST_ORDERS" });
          return;
        }

        if (isCloudFirestore()) {
          const db = getFirestore();
          const snap = await db.collection("orders").where("state", "in", ["DRAFT", "CANCELLED", "REJECTED"]).get();
          const batch = db.batch();
          snap.forEach((d) => batch.delete(d.ref));
          await batch.commit();
          sendJson(res, 200, { success: true, deletedCount: snap.size });
        } else {
          const pool = getPool();
          const { rowCount } = await pool.query("DELETE FROM orders WHERE state IN ('DRAFT', 'CANCELLED', 'REJECTED')");
          sendJson(res, 200, { success: true, deletedCount: rowCount });
        }
      })
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  return false;
}

