      white-space: nowrap;
      color: var(--ink-secondary);
    }

    .log-line.log-error {
      color: var(--signal-red);
      font-weight: 500;
    }

    /* Stepped Bar Chart */
    .chart-container {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .bar-chart {
      display: flex;
      align-items: flex-end;
      gap: 6px;
      height: 110px;
      padding-bottom: 6px;
      border-bottom: 1px solid var(--border-hairline);
    }

    .bar-col {
      flex: 1;
      height: 100%;
      display: flex;
      align-items: flex-end;
    }

    .bar-fill {
      width: 100%;
      background: var(--ink-primary);
      border-radius: 1px 1px 0 0;
      min-height: 4px;
    }

    .chart-labels {
      display: flex;
      justify-content: space-between;
      font-size: 10.5px;
      color: var(--ink-muted);
    }

    .chart-stats {
      font-family: var(--font-mono);
      font-size: 11.5px;
      color: var(--ink-primary);
      margin-top: 4px;
    }

    /* Modals */
    .modal {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(20, 19, 16, 0.55);
      backdrop-filter: blur(2px);
      -webkit-backdrop-filter: blur(2px);
      z-index: 1000;
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      padding: 20px 14px;
      box-sizing: border-box;
    }

    .modal-content {
      background: var(--bg-raised);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-md);
      padding: 22px 24px;
      width: 100%;
      max-width: 520px;
      max-height: calc(100vh - 40px);
      display: flex;
      flex-direction: column;
      margin: auto;
      box-shadow: 0 16px 40px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.08), inset 0 -1px 0 rgba(0, 0, 0, 0.1);
      position: relative;
      box-sizing: border-box;
      overflow-y: auto;
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
    }

    .modal-content.has-body,
    .modal-content:has(.modal-body) {
      overflow: hidden;
      padding: 20px 24px 16px 24px;
    }

    .modal-header {
      flex-shrink: 0;
      margin-bottom: 14px;
      padding-bottom: 10px;
      border-bottom: 1px solid var(--border-hairline);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .modal-body {
      flex: 1 1 auto;
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      padding-right: 6px;
      min-height: 0;
    }

    .modal-footer {
      flex-shrink: 0;
      display: flex;
      justify-content: flex-end;
      gap: 8px;
      border-top: 1px solid var(--border-hairline);
      padding-top: 14px;
      margin-top: 14px;
    }

    @media (max-width: 600px) {
      .modal {
        padding: 10px 8px;
      }
      .modal-content {
        padding: 16px 14px;
        max-height: calc(100vh - 20px);
      }
      .modal-content.has-body,
      .modal-content:has(.modal-body) {
        padding: 14px 14px 12px 14px;
      }
    }

    .form-group {
      margin-bottom: 14px;
    }

    .form-group label {
      display: block;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
      margin-bottom: 4px;
    }

    .form-control {
      width: 100%;
      background: var(--bg-paper);
      border: 1px solid var(--border-hairline);
