  <script>
    // Automatic server-side session credentials for all dashboard API requests
    const _origFetch = window.fetch;
    window.fetch = function(url, init) {
      init = Object.assign({}, init);
      init.credentials = init.credentials || 'same-origin';
      const token = localStorage.getItem('xeurie_token');
      if (token) {
        if (typeof Headers !== 'undefined' && init.headers instanceof Headers) {
          if (!init.headers.has('Authorization')) {
            init.headers.set('Authorization', 'Bearer ' + token);
          }
        } else if (Array.isArray(init.headers)) {
          const hasAuth = init.headers.some(h => Array.isArray(h) && String(h[0]).toLowerCase() === 'authorization');
          if (!hasAuth) {
            init.headers.push(['Authorization', 'Bearer ' + token]);
          }
        } else {
          init.headers = Object.assign({}, init.headers);
          if (!init.headers['Authorization'] && !init.headers['authorization']) {
            init.headers['Authorization'] = 'Bearer ' + token;
          }
        }
      }
      return _origFetch.call(this, url, init).then(res => {
        if (res.status === 401 && !String(url).includes('/api/auth/')) {
          localStorage.removeItem('xeurie_auth');
          localStorage.removeItem('xeurie_token');
          const overlay = document.getElementById('loginOverlay');
          if (overlay) overlay.style.display = 'flex';
        }
        return res;
      });
    };

    const accountCredentialsCache = new Map();
    var globalData = { products: [], orders: [], subscriptions: [], accounts: [], customers: [], restocks: [], expenses: [] };

    function escapeHtml(str) {
      if (str === null || str === undefined) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    function escapeAttr(str) {
      if (str === null || str === undefined) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    }

    function safeTelegramLink(username) {
      if (!username) return null;
      const clean = String(username).trim().replace(/^@/, '');
      if (!/^[a-zA-Z0-9_]{3,64}$/.test(clean)) return null;
      return 'https://t.me/' + clean;
    }

    function safeJson(val) {
      if (!val) return {};
      if (typeof val === 'object') return val;
      try { return JSON.parse(val); } catch (e) { return {}; }
    }

    function showTab(name, btn) {
      document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');
      document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
      const target = document.getElementById('tab-' + name);
      if (target) target.style.display = 'block';
      if (btn) btn.classList.add('active');
    }

    function openModal(id) { 
      if (id === 'addOrderModal') populateManualOrderModal();
      const el = document.getElementById(id);
      if (!el) return;
      el.style.display = 'flex';
      el.scrollTop = 0;
      document.body.style.overflow = 'hidden';
      const body = el.querySelector('.modal-body');
      if (body) body.scrollTop = 0;
    }
    function closeModal(id) { 
      const el = document.getElementById(id);
      if (el) el.style.display = 'none';
      const anyOpen = Array.from(document.querySelectorAll('.modal')).some(m => m.style.display === 'flex');
      if (!anyOpen) document.body.style.overflow = '';
    }
    function openAddModal() { openModal('addModal'); }

    window.addEventListener('click', function(e) {
      if (e.target && e.target.classList && e.target.classList.contains('modal')) {
        closeModal(e.target.id);
      }
    });
    window.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        const modals = document.querySelectorAll('.modal');
        modals.forEach(m => {
          if (m.style.display === 'flex') closeModal(m.id);
        });
      }
    });

    async function loadAll() {
      try {
        const res = await fetch('/api/dashboard/bootstrap').then(r => r.json()).catch(() => null);
        if (!res) return;

        accountCredentialsCache.clear();

        globalData = {
          products: res.products || [],
          orders: res.orders || [],
          subscriptions: res.subscriptions || [],
          accounts: res.accounts || [],
          customers: res.customers || [],
          restocks: res.restocks || [],
          expenses: res.expenses || [],
          suppliers: res.suppliers || [],
          resellers: res.resellers || [],
        };

        renderAnalytics(res.analytics || {});
        renderProducts(globalData.products);
        renderOrders(globalData.orders);
        renderSubscriptions(globalData.subscriptions);
        renderAccounts(globalData.accounts);
        renderCustomers(globalData.customers);
        renderRestocks(globalData.restocks);
        renderExpenses(globalData.expenses);
        renderSuppliers(globalData.suppliers);
        renderResellers(globalData.resellers);
        populateSettings(res.settings || {});

        document.getElementById('badge-orders-nav').innerText = globalData.orders.length;
        document.getElementById('badge-subs-nav').innerText = globalData.subscriptions.length;
        const bSup = document.getElementById('badge-suppliers-nav');
        if (bSup) bSup.innerText = globalData.suppliers.length;
        const bRes = document.getElementById('badge-resellers-nav');
        if (bRes) bRes.innerText = globalData.resellers.length;
      } catch (err) {
        console.error('Data load error:', err);
      }
    }

    function renderAnalytics(data) {
      document.getElementById('stat-rev-today').innerText = '₱' + Number(data.today?.revenue || 0).toLocaleString('en-US', {minimumFractionDigits: 2});
      document.getElementById('stat-profit-today').innerText = '₱' + Number(data.today?.gross_profit || 0).toLocaleString('en-US', {minimumFractionDigits: 2});
      document.getElementById('stat-orders-today').innerText = (data.today?.orders_count || 0) + ' Completed Orders';
      document.getElementById('stat-margin-today').innerText = (data.today?.margin_percent || 0) + '% Gross Margin';
      document.getElementById('stat-rev-30d').innerText = '₱' + Number(data.last_30_days?.revenue || 0).toLocaleString('en-US', {minimumFractionDigits: 2});
      document.getElementById('stat-profit-30d').innerText = 'Profit: ₱' + Number(data.last_30_days?.gross_profit || 0).toFixed(2);
      document.getElementById('stat-expiring-3d').innerText = data.expiring_soon_count || 0;
    }

    function renderProducts(products) {
      const tbody = document.getElementById('products-tbody');
      const selectAcc = document.getElementById('acc-product-id');
      const selectRestock = document.getElementById('restock-product-id');
      if (selectAcc) selectAcc.innerHTML = (products || []).map(p => '<option value="' + escapeHtml(p.id) + '">' + escapeHtml(p.name) + '</option>').join('');
      if (selectRestock) selectRestock.innerHTML = (products || []).map(p => '<option value="' + escapeHtml(p.id) + '">' + escapeHtml(p.name) + '</option>').join('');

      tbody.innerHTML = (products || []).map(p => {
        const variantsHtml = (p.variants || []).map(v => 
          '<div style="display:flex; align-items:center; justify-content:space-between; gap:6px; margin-bottom:4px; padding:3px 6px; border:1px solid var(--border-hairline); border-radius:3px; background:var(--bg-paper); font-size:11.5px;" class="mono-nums">' +
            '<span><strong>' + escapeHtml(v.name) + '</strong> · <strong>₱' + Number(v.price).toFixed(0) + '</strong> <span style="color:var(--ink-muted);">(Puhunan: ₱' + Number(v.cost||0).toFixed(0) + ')</span></span>' +
            '<span style="display:inline-flex; gap:3px;">' +
              '<button class="btn btn-secondary btn-sm" style="padding:1px 5px; font-size:10px;" onclick="openEditVariantModal(' + Number(p.id) + ', ' + Number(v.id) + ')">✏️</button>' +
              '<button class="btn btn-danger btn-sm" style="padding:1px 5px; font-size:10px;" onclick="deleteVariant(' + Number(v.id) + ')">🗑️</button>' +
            '</span>' +
          '</div>'
        ).join('') || '<span style="color:var(--ink-muted); font-size:11.5px;">No plans</span>';

        const statusSelectHtml =
          '<select class="form-control" style="width:auto; min-width:120px; padding:3px 6px; font-size:11px; font-weight:600;" onchange="updateProductStatus(' + Number(p.id) + ', this.value)">' +
            '<option value="AVAILABLE"' + (p.status === 'AVAILABLE' ? ' selected' : '') + '>🟢 AVAILABLE</option>' +
            '<option value="LIMITED"' + (p.status === 'LIMITED' ? ' selected' : '') + '>🟡 LIMITED</option>' +
            '<option value="SOLD_OUT"' + (p.status === 'SOLD_OUT' ? ' selected' : '') + '>🔴 SOLD OUT</option>' +
            '<option value="PRE_ORDER"' + (p.status === 'PRE_ORDER' ? ' selected' : '') + '>⏳ PRE-ORDER</option>' +
          '</select>';

        return '<tr>' +
          '<td><strong>' + escapeHtml(p.name) + '</strong></td>' +
          '<td><span class="chip">' + escapeHtml(p.category || 'General') + '</span></td>' +
          '<td>' + statusSelectHtml + '</td>' +
          '<td><input class="form-control mono-nums" style="width:70px; padding:3px 6px;" value="' + (p.stock===null?'':escapeHtml(String(p.stock))) + '" placeholder="♾️" onchange="updateStock(' + Number(p.id) + ', this.value)"></td>' +
          '<td style="min-width:260px;">' +
            variantsHtml +
            '<button class="btn btn-secondary btn-sm" style="margin-top:3px; font-size:10.5px; padding:2px 6px;" onclick="openAddVariantModal(' + Number(p.id) + ')">➕ Add Plan</button>' +
          '</td>' +
          '<td><button class="btn btn-secondary btn-sm" onclick="toggleVisibility(' + Number(p.id) + ')">' + (p.visibility==='VISIBLE'?'Visible':'Hidden') + '</button></td>' +
          '<td>' +
            '<button class="btn btn-secondary btn-sm" style="margin-right:4px;" onclick="openEditProductModal(' + Number(p.id) + ')">✏️ Edit</button>' +
            '<button class="btn btn-danger btn-sm" onclick="archiveProduct(' + Number(p.id) + ')">Archive</button>' +
          '</td>' +
        '</tr>';
      }).join('');
    }

    function renderOrders(orders) {
      const tbody = document.getElementById('orders-tbody');
      const inboxTbody = document.getElementById('inbox-tbody');

      if (!Array.isArray(orders) || orders.length === 0) {
        if (inboxTbody) inboxTbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--ink-muted); padding: 20px;">No pending orders. All caught up!</td></tr>';
        if (tbody) tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--ink-muted); padding: 20px;">No orders recorded.</td></tr>';
        return;
      }

      try {
        const pending = orders.filter(o => o.state === 'PENDING_OWNER');
        if (inboxTbody) {
          inboxTbody.innerHTML = pending.length === 0 
            ? '<tr><td colspan="5" style="text-align: center; color: var(--ink-muted); padding: 20px;">No pending orders in inbox.</td></tr>'
            : pending.map(o => {
                const chatLink = safeTelegramLink(o.customer_username);
                const pSnap = safeJson(o.product_snapshot);
                const vSnap = safeJson(o.variant_snapshot);
                const pName = pSnap.name || o.product_name || 'Product';
                const vName = vSnap.name || o.variant_name || 'Plan';
                const customerDisplay = o.customer_username ? '@' + escapeHtml(o.customer_username) : 'ID: ' + escapeHtml(o.customer_id);
                return '<tr>' +
                  '<td><code class="cell-code">' + escapeHtml(o.code || o.id) + '</code></td>' +
                  '<td>' + customerDisplay + '</td>' +
                  '<td>' + escapeHtml(pName) + ' (' + escapeHtml(vName) + ')</td>' +
                  '<td class="mono-nums"><strong>₱' + Number(o.total || 0).toFixed(2) + '</strong></td>' +
                  '<td>' +
                    (chatLink ? '<a href="' + escapeHtml(chatLink) + '" target="_blank" rel="noopener noreferrer" class="btn btn-secondary btn-sm" style="margin-right:4px;">💬 Chat</a>' : '') +
                    '<button class="btn btn-primary btn-sm" onclick="acceptOrder(' + Number(o.id) + ')">Accept</button>' +
                  '</td>' +
                '</tr>';
              }).join('');
        }

        if (tbody) {
          tbody.innerHTML = orders.map(o => {
            const chatLink = safeTelegramLink(o.customer_username);
            const pSnap = safeJson(o.product_snapshot);
            const vSnap = safeJson(o.variant_snapshot);
            const pName = pSnap.name || o.product_name || 'Product';
            const vName = vSnap.name || o.variant_name || 'Plan';

            const isFailed = o.state === 'CANCELLED' || o.state === 'REJECTED';
            const stateGlyph = o.state === 'COMPLETED' || o.state === 'DELIVERED' 
              ? '<span class="ink-glyph ready">●</span>' 
              : (isFailed ? '<span class="ink-glyph failed">⊗</span>' : '<span class="ink-glyph building">◐</span>');

            const assignBtn = (o.state === 'PAID' || o.state === 'ACCEPTED')
              ? '<button class="btn btn-primary btn-sm" style="margin-right:4px;" onclick="openAssignModal(' + Number(o.id) + ')">🔑 Assign</button>'
              : '';

            const assignedInfo = (o.assigned_account_label || o.assigned_account_id)
              ? '<div style="font-size:11px; color:#137333; margin-top:3px; white-space:nowrap;">' +
                  '🔑 ' + escapeHtml(o.assigned_account_label || ('Acc #' + o.assigned_account_id)) +
                  (o.assigned_profile_name ? ' <span style="background:#e6f4ea;border:1px solid #a8dab5;padding:1px 5px;border-radius:3px;font-weight:600;">👤 ' + escapeHtml(o.assigned_profile_name) + (o.assigned_profile_pin ? ' (PIN: ' + escapeHtml(o.assigned_profile_pin) + ')' : '') + '</span>' : '') +
                '</div>'
              : '';

            const customerDisplay = o.customer_username ? '@' + escapeHtml(o.customer_username) : 'ID: ' + escapeHtml(o.customer_id);

            return '<tr class="' + (isFailed ? 'row-failed' : '') + '">' +
              '<td style="text-align: center;"><input type="checkbox" class="order-checkbox" value="' + escapeHtml(o.id) + '" onchange="onOrderCheckboxChange()"></td>' +
              '<td><code class="cell-code">' + escapeHtml(o.code || o.id) + '</code></td>' +
              '<td>' + customerDisplay + (chatLink ? ' <a href="' + escapeHtml(chatLink) + '" target="_blank" rel="noopener noreferrer" style="text-decoration:underline;">💬</a>' : '') + '</td>' +
              '<td>' + escapeHtml(pName) + ' (' + escapeHtml(vName) + ')' + assignedInfo + '</td>' +
              '<td class="mono-nums">' + (o.quantity || 1) + '</td>' +
              '<td class="mono-nums"><strong>₱' + Number(o.total || 0).toFixed(2) + '</strong></td>' +
              '<td class="mono-nums">+₱' + Number(o.gross_profit_snapshot || 0).toFixed(2) + '</td>' +
              '<td>' + stateGlyph + ' ' + escapeHtml(o.state || 'UNKNOWN') + '</td>' +
              '<td>' +
                assignBtn +
                '<button class="btn btn-secondary btn-sm" style="margin-right:4px;" title="Copy Payment" onclick="copyOrderPayment(' + Number(o.id) + ')">📋 Pay</button>' +
                '<button class="btn btn-secondary btn-sm" style="margin-right:4px;" title="Copy Delivery" onclick="copyOrderDelivery(' + Number(o.id) + ')">📋 Deliv</button>' +
                '<select class="form-control" style="width:auto; display:inline-block; padding:2px 6px;" onchange="updateOrderState(' + Number(o.id) + ', this.value)">' +
                  '<option value="' + escapeHtml(o.state) + '" selected>' + escapeHtml(o.state) + '</option>' +
                  '<option value="ACCEPTED">ACCEPTED</option>' +
                  '<option value="PAID">PAID</option>' +
                  '<option value="DELIVERED">DELIVERED</option>' +
                  '<option value="COMPLETED">COMPLETED</option>' +
                  '<option value="CANCELLED">CANCELLED</option>' +
                  '<option value="REJECTED">REJECTED</option>' +
                '</select>' +
                '<button class="btn btn-danger btn-sm" style="margin-left:4px;" title="Delete Order" onclick="deleteSingleOrder(' + Number(o.id) + ')">🗑️</button>' +
              '</td>' +
            '</tr>';
          }).join('');
        }
      } catch (err) {
        console.error('Error rendering orders:', err);
        if (tbody) tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--signal-red); padding: 20px;">Failed to render orders table.</td></tr>';
      }
    }

    function filterOrderState(st, btn) {
      document.querySelectorAll('.seg-btn').forEach(b => b.classList.remove('active'));
      if (btn) btn.classList.add('active');
      if (st === 'ALL') {
        renderOrders(globalData.orders);
      } else {
        renderOrders((globalData.orders || []).filter(o => o.state === st));
      }
    }

