    async function fetchAccountCredentials(accId) {
      if (accountCredentialsCache.has(accId)) {
        return accountCredentialsCache.get(accId);
      }
      try {
        const res = await fetch('/api/accounts/' + accId + '/credentials');
        if (!res.ok) {
          throw new Error('Failed to fetch credentials (' + res.status + ')');
        }
        const data = await res.json();
        accountCredentialsCache.set(accId, data);
        const acc = (globalData.accounts || []).find(a => a.id === accId);
        if (acc) {
          if (data.password !== undefined) acc.password = data.password;
          if (data.two_factor_link !== undefined) acc.two_factor_link = data.two_factor_link;
          if (data.profiles !== undefined) acc.profiles = data.profiles;
        }
        return data;
      } catch (err) {
        console.error('Error fetching credentials for account ' + accId + ':', err);
        throw err;
      }
    }

    let currentAccountFilter = 'ALL';
    function filterAccountView(f) {
      currentAccountFilter = f;
      renderAccounts(globalData.accounts);
    }

    function renderAccounts(accs) {
      const tbody = document.getElementById('accounts-tbody');
      let filtered = accs || [];
      if (currentAccountFilter === 'AVAILABLE') {
        filtered = filtered.filter(a => {
          if (a.status === 'AVAILABLE') return true;
          if (Array.isArray(a.profiles) && a.profiles.length > 0) {
            return a.profiles.some(p => p.status !== 'ASSIGNED');
          }
          return false;
        });
      }
      if (currentAccountFilter === 'ASSIGNED') {
        filtered = filtered.filter(a => {
          if (a.status === 'ASSIGNED') return true;
          if (Array.isArray(a.profiles) && a.profiles.length > 0) {
            return a.profiles.every(p => p.status === 'ASSIGNED');
          }
          return false;
        });
      }

      tbody.innerHTML = filtered.length === 0 ? '<tr><td colspan="9" style="text-align: center; color: var(--ink-muted); padding: 20px;">No accounts in this view.</td></tr>' : filtered.map(a => {
        let totalProfs = 0;
        let soldProfs = 0;
        if (Array.isArray(a.profiles) && a.profiles.length > 0) {
          totalProfs = a.profiles.length;
          soldProfs = a.profiles.filter(p => p.status === 'ASSIGNED').length;
        }

        let statusBadge = '';
        if (a.status === 'ASSIGNED' || (totalProfs > 0 && soldProfs === totalProfs)) {
          statusBadge = '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;white-space:nowrap;background:#e6f4ea;color:#137333;border:1px solid #a8dab5;">🟢 ASSIGNED</span>';
        } else if (totalProfs > 0 && soldProfs > 0) {
          statusBadge = '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;white-space:nowrap;background:#fef7e0;color:#b06000;border:1px solid #f9ab00;">🟡 ' + soldProfs + '/' + totalProfs + ' SOLD (AVAILABLE)</span>';
        } else if (a.status === 'AVAILABLE') {
          statusBadge = '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;white-space:nowrap;background:#fce8e6;color:#c5221f;border:1px solid #f5b7b1;">🔴 AVAILABLE (UNSOLD)</span>';
        } else {
          statusBadge = '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;white-space:nowrap;background:#f1f3f4;color:#5f6368;border:1px solid #dadce0;">⚪ ' + escapeHtml(a.status || 'DISABLED') + '</span>';
        }

        const emailVal = a.email || a.label || '-';
        const emailDisplay = '<div style="display:flex;align-items:center;gap:5px;white-space:nowrap;">' +
          '<strong class="mono-nums" style="font-size:12px;">' + escapeHtml(emailVal) + '</strong>' +
          (emailVal !== '-' ? '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;white-space:nowrap;flex-shrink:0;" title="Copy Email" onclick="copyAccountEmail(' + a.id + ')">📋</button>' : '') +
          '</div>' +
          (a.label && a.label !== a.email ? '<div style="font-size:10.5px;color:var(--ink-muted);margin-top:2px;white-space:nowrap;">' + escapeHtml(a.label) + '</div>' : '');

        let pwdDisplay = '<span style="color:var(--ink-muted);font-size:11px;font-style:italic;">None</span>';
        if (a.has_password || a.password) {
          const cachedVal = a.password || '';
          pwdDisplay = '<div style="display:flex;align-items:center;gap:4px;white-space:nowrap;">' +
            '<span id="pwd-' + a.id + '" data-val="' + (cachedVal ? escapeHtml(cachedVal).replace(/"/g, '&quot;') : '') + '" style="font-family:monospace;font-size:12px;background:var(--surface-sunken);padding:2px 6px;border-radius:4px;letter-spacing:1px;white-space:nowrap;">••••••••</span>' +
            '<button id="btn-pwd-' + a.id + '" class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;white-space:nowrap;flex-shrink:0;" title="Show/Hide Password" onclick="togglePasswordView(' + a.id + ')">👁️</button>' +
            '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;white-space:nowrap;flex-shrink:0;" title="Copy Password" onclick="copyAccountPassword(' + a.id + ')">📋</button>' +
          '</div>';
        }

        // Profiles & PINs display
        let profDisplay = '<span style="color:var(--ink-muted);font-size:11px;font-style:italic;">None</span>';
        if (Array.isArray(a.profiles) && a.profiles.length > 0) {
          profDisplay = '<div style="display:flex;flex-direction:column;gap:4px;min-width:210px;">' +
            a.profiles.map((p, pIdx) => {
              const isAssigned = p.status === 'ASSIGNED';
              const orderTag = isAssigned
                ? '<span style="background:#e6f4ea;color:#137333;border:1px solid #a8dab5;border-radius:3px;padding:1px 5px;font-size:10px;font-weight:700;margin-left:4px;">🟢 ' + escapeHtml(p.assigned_order_code || 'Sold') + '</span>'
                : '<span style="background:#fce8e6;color:#c5221f;border:1px solid #f5b7b1;border-radius:3px;padding:1px 5px;font-size:10px;font-weight:700;margin-left:4px;">🔴 Available</span>';
              const pinVal = p.pin || (p.has_pin ? '••••' : '');
              const pinHtml = pinVal ? ' <span style="color:var(--ink-muted);">(PIN: <code class="mono-nums" style="font-weight:bold;">' + escapeHtml(pinVal) + '</code>)</span>' : '';
              return '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;background:var(--surface-sunken);border:1px solid var(--border-subtle);border-radius:4px;padding:3px 8px;font-size:11px;white-space:nowrap;">' +
                '<span style="white-space:nowrap;">👤 <strong>' + escapeHtml(p.name) + '</strong>' + pinHtml + orderTag + '</span>' +
                '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:9px;line-height:1;white-space:nowrap;flex-shrink:0;" title="Copy Profile & PIN" onclick="copyAccountProfile(' + a.id + ', ' + pIdx + ')">📋</button>' +
              '</div>';
            }).join('') +
          '</div>';
        }

        // 2FA Link display
        let twoFaDisplay = '<span style="color:var(--ink-muted);font-size:11px;font-style:italic;">None</span>';
        if (a.has_2fa || a.two_factor_link) {
          twoFaDisplay = '<div style="display:flex;align-items:center;gap:4px;white-space:nowrap;">' +
            '<button class="btn btn-secondary btn-sm" style="padding:2px 7px;font-size:10.5px;color:#1a73e8;font-weight:600;white-space:nowrap;flex-shrink:0;" title="Open 2FA link" onclick="openAccount2FA(' + a.id + ')">🔗 Open 2FA</button>' +
            '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;white-space:nowrap;flex-shrink:0;" title="Copy 2FA Link/Key" onclick="copyAccount2FA(' + a.id + ')">📋</button>' +
          '</div>';
        }

        return '<tr>' +
          '<td style="white-space:nowrap;">' + emailDisplay + '</td>' +
          '<td style="white-space:nowrap;">' + pwdDisplay + '</td>' +
          '<td>' + profDisplay + '</td>' +
          '<td style="white-space:nowrap;">' + twoFaDisplay + '</td>' +
          '<td style="white-space:nowrap;">' +
            '<div style="display:flex;align-items:center;gap:6px;">' +
              '<strong>' + escapeHtml(a.product_name || 'Product') + '</strong>' +
              '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;" title="Edit Product / Account" onclick="openEditAccountModal(' + a.id + ')">✏️</button>' +
            '</div>' +
          '</td>' +
          '<td style="white-space:nowrap;">' + statusBadge + '</td>' +
          '<td style="white-space:nowrap;">' + (a.current_customer_username ? '@' + escapeHtml(a.current_customer_username) : (a.current_customer_id ? '<span class="mono-nums">ID: ' + escapeHtml(a.current_customer_id) + '</span>' : '<span style="color:var(--ink-muted);">-</span>')) + '</td>' +
          '<td>' + (a.notes ? escapeHtml(a.notes) : '<span style="color:var(--ink-muted);">-</span>') + '</td>' +
          '<td style="white-space:nowrap;">' +
            '<div style="display:flex;gap:4px;white-space:nowrap;">' +
              '<button class="btn btn-secondary btn-sm" title="Toggle Status" onclick="toggleAccStatus(' + Number(a.id) + ')">Toggle</button>' +
              '<button class="btn btn-secondary btn-sm" title="Copy Full Credentials Info" onclick="copyFullAccountInfo(' + Number(a.id) + ')">📋 Info</button>' +
              '<button class="btn btn-secondary btn-sm" title="Edit Credentials" onclick="openEditAccountModal(' + Number(a.id) + ')">✏️</button>' +
              '<button class="btn btn-danger btn-sm" title="Delete Account" onclick="deleteAccount(' + Number(a.id) + ')">🗑️</button>' +
            '</div>' +
          '</td>' +
        '</tr>';
      }).join('');
    }

