    async function copyOrderMessage(orderId, type) {
      const order = globalData.orders.find(o => o.id === orderId);
      if (!order) return;
      const pSnap = safeJson(order.product_snapshot);
      const vSnap = safeJson(order.variant_snapshot);

      const savedPayTpl = globalData.settings?.template_payment || document.getElementById('tpl-payment')?.value;
      const savedDelivTpl = globalData.settings?.template_delivery || document.getElementById('tpl-delivery')?.value;

      const tpl = type === 'payment' 
        ? (savedPayTpl || defaultTemplates.payment)
        : (savedDelivTpl || defaultTemplates.delivery);

      let acc = order.assigned_account_id ? (globalData.accounts || []).find(a => a.id === order.assigned_account_id) : null;
      let accEmail = acc ? (acc.email || acc.label || '') : '';
      let accPwd = acc?.password || '';
      let accProf = order.assigned_profile_name || '';
      let accPin = order.assigned_profile_pin && order.assigned_profile_pin !== '••••'
        ? order.assigned_profile_pin
        : '';
      const profFromAcc = acc?.profiles?.find(p => p.name === accProf);
      const profHasPin = Boolean(accPin || (profFromAcc && (profFromAcc.has_pin || (profFromAcc.pin && profFromAcc.pin !== '••••'))));
      let acc2Fa = acc?.two_factor_link || '';

      if (acc && order.assigned_account_id && type === 'delivery') {
        const needsFetch = (acc.has_password && !accPwd) ||
                           (acc.has_2fa && !acc2Fa) ||
                           (profHasPin && !accPin);
        if (needsFetch) {
          try {
            const creds = await fetchAccountCredentials(order.assigned_account_id);
            if (creds) {
              accEmail = creds.email || accEmail;
              accPwd = creds.password || accPwd;
              acc2Fa = creds.two_factor_link || acc2Fa;
              if (Array.isArray(creds.profiles)) {
                const foundProf = creds.profiles.find(p => p.name === accProf);
                if (foundProf && foundProf.pin && foundProf.pin !== '••••') {
                  accPin = foundProf.pin;
                }
              }
            }
          } catch (e) {
            console.warn('Could not fetch credentials for delivery template:', e);
          }
        }
      }

      const credLines = [];
      if (accEmail) credLines.push('📧 Email/Login: ' + accEmail);
      if (accPwd) credLines.push('🔑 Password: ' + accPwd);
      if (accProf) credLines.push('👤 Profile: ' + accProf + (accPin ? ' (PIN: ' + accPin + ')' : ''));
      if (acc2Fa) credLines.push('🛡️ 2FA Link: ' + acc2Fa);
      const credBlock = credLines.length > 0 ? credLines.join(String.fromCharCode(10)) : '';

      let msg = tpl
        .replace(/{{customer}}/g, order.customer_username ? '@' + order.customer_username : (order.customer_name || 'Customer'))
        .replace(/{{order_code}}/g, order.code)
        .replace(/{{product}}/g, pSnap.name || 'Product')
        .replace(/{{plan}}/g, vSnap.name || 'Plan')
        .replace(/{{total}}/g, Number(order.total || 0).toFixed(2))
        .replace(/{{expiration_date}}/g, 'in 30 days')
        .replace(/{{email}}/g, accEmail)
        .replace(/{{password}}/g, accPwd)
        .replace(/{{profile}}/g, accProf)
        .replace(/{{pin}}/g, accPin)
        .replace(/{{2fa}}/g, acc2Fa)
        .replace(/{{two_factor_link}}/g, acc2Fa)
        .replace(/{{credentials}}/g, credBlock);

      if (type === 'delivery' && credBlock && !tpl.includes('{{credentials}}') && !tpl.includes('{{email}}')) {
        msg += String.fromCharCode(10) + String.fromCharCode(10) + '📦 Account Credentials:' + String.fromCharCode(10) + credBlock;
      }

      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(msg).then(() => {
          alert('📋 Copied to clipboard! Ready to send to customer.');
        }).catch(() => fallbackCopy(msg));
      } else {
        fallbackCopy(msg);
      }
    }

