        }

        await AuditService.log({ action: "BULK_DELETE_ORDERS", entity: "order", details: `Deleted ${ids.length} orders` });
        sendJson(res, 200, { success: true, count: ids.length });
      })
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 11d. REST API — Clear All Orders
  if (pathname === "/api/orders/clear-all" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const scope = body.scope || "ALL"; // ALL or PENDING

        if (isCloudFirestore()) {
          const db = getFirestore();
          const snap = scope === "PENDING"
            ? await db.collection("orders").where("state", "==", "PENDING_OWNER").get()
            : await db.collection("orders").get();

          const batch = db.batch();
          snap.forEach((d) => batch.delete(d.ref));
          await batch.commit();
          invalidateFirestoreCache("orders");
          sendJson(res, 200, { success: true, count: snap.size });
        } else {
          const pool = getPool();
          const query = scope === "PENDING"
            ? "DELETE FROM orders WHERE state = 'PENDING_OWNER'"
            : "DELETE FROM orders";
          const { rowCount } = await pool.query(query);
          sendJson(res, 200, { success: true, count: rowCount });
        }

        await AuditService.log({ action: "CLEAR_ALL_ORDERS", entity: "order", details: `Cleared all orders (scope: ${scope})` });
      })
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 12. REST API — Assign Account to Order
  const assignMatch = pathname.match(/^\/api\/orders\/(\d+)\/assign$/);
  if (assignMatch && method === "POST") {
    const orderId = Number(assignMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const accountId = Number(body.accountId);
        const durationDays = Number(body.durationDays) || 30;
        const profileName = body.profileName ? String(body.profileName).trim() : null;
        const result = await OrderService.assignAccountToOrder(orderId, accountId, durationDays, "web_dashboard", profileName);
        sendJson(res, 200, {
          success: true,
          ...result,
          account: result.account ? sanitizeAccountForListing(result.account) : undefined,
        }, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 13. REST API — Subscriptions List & Renew
  if (pathname === "/api/subscriptions" && method === "GET") {
    SubscriptionService.listSubscriptions()
      .then((subscriptions) => sendJson(res, 200, { subscriptions }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  const renewMatch = pathname.match(/^\/api\/subscriptions\/(\d+)\/renew$/);
  if (renewMatch && method === "POST") {
    const id = Number(renewMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const days = body.days ? Number(body.days) : 30;
        const result = await SubscriptionService.renewSubscription(id, days);
        await AuditService.log({ action: "RENEW_SUBSCRIPTION", entity: "subscription", entityId: id, details: `Renewed subscription ${id} by +${days} days` });
        sendJson(res, 200, { success: true, subscription: result });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  const subDelMatch = pathname.match(/^\/api\/subscriptions\/(\d+)$/);
  if (subDelMatch && method === "DELETE") {
    const id = Number(subDelMatch[1]);
    SubscriptionService.deleteSubscription(id)
      .then((success) => {
        AuditService.log({ action: "DELETE_SUBSCRIPTION", entity: "subscription", entityId: id, details: `Deleted subscription ${id}` });
        sendJson(res, 200, { success });
      })
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 14. REST API — Account Inventory
  if (pathname === "/api/accounts" && method === "GET") {
    AccountService.listAccounts()
      .then((accounts) => sendJson(res, 200, {
        accounts: (Array.isArray(accounts) ? accounts : []).map(sanitizeAccountForListing)
      }, req))
      .catch((err) => sendJson(res, 500, { error: err.message }, req));
    return true;
  }

  // 14b. REST API — On-Demand Credential Vault Retrieval (Single Account Instance)
  const accCredsMatch = pathname.match(/^\/api\/accounts\/(\d+)\/(?:credentials|reveal)$/);
  if (accCredsMatch && (method === "GET" || method === "POST")) {
    const id = Number(accCredsMatch[1]);
    AccountService.getAccountById(id)
      .then(async (account) => {
        if (!account) {
          sendJson(res, 404, { error: "Account not found" }, req);
          return;
        }
        let rawProfiles = account.profiles;
        if (typeof rawProfiles === "string") {
          try {
            rawProfiles = JSON.parse(rawProfiles);
          } catch {
            // retain raw
          }
        }
        await AuditService.log({
          action: "REVEAL_ACCOUNT_CREDENTIALS",
          entity: "account",
          entityId: id,
          details: `Accessed credentials for account #${id} (${account.label || account.email || "unlabeled"})`,
        }).catch(() => {});

        sendJson(res, 200, {
          id: account.id,
          product_id: account.product_id,
          product_name: account.product_name,
          label: account.label,
          email: account.email,
          password: account.password,
          two_factor_link: account.two_factor_link,
          profiles: rawProfiles,
          status: account.status,
          notes: account.notes,
          credentials: {
            email: account.email,
            password: account.password,
            two_factor_link: account.two_factor_link,
            profiles: rawProfiles,
          },
        }, req);
      })
      .catch((err) => sendJson(res, 500, { error: err.message }, req));
    return true;
  }

  if (pathname === "/api/accounts" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const sanitizedProfiles = Array.isArray(body.profiles) ? body.profiles.map((p: any) => ({
          ...p,
          name: sanitizeUserInput(String(p.name || "Profile"), 100),
          pin: p.pin !== undefined && p.pin !== null ? sanitizeUserInput(String(p.pin), 20) : null,
        })) : null;

        const label = body.label ? sanitizeUserInput(String(body.label), 100) : (body.email ? sanitizeUserInput(String(body.email), 100) : "Account");
        const account = await AccountService.createAccount({
          product_id: Number(body.productId),
          label,
          email: body.email || null,
          password: body.password || null,
          two_factor_link: body.two_factor_link || null,
          profiles: sanitizedProfiles,
          notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : null,
        });
        await AuditService.log({ action: "CREATE_ACCOUNT", entity: "account", entityId: account.id, details: `Added account instance ${account.label}` });
        sendJson(res, 201, { account: sanitizeAccountForListing(account) }, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }, req));
    return true;
  }

  const accPatchMatch = pathname.match(/^\/api\/accounts\/(\d+)(?:\/status)?$/);
  if (accPatchMatch && method === "PATCH") {
    const id = Number(accPatchMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const prodId = body.product_id !== undefined ? Number(body.product_id) : (body.productId !== undefined ? Number(body.productId) : undefined);
        const sanitizedProfiles = Array.isArray(body.profiles) ? body.profiles.map((p: any) => ({
          ...p,
          name: sanitizeUserInput(String(p.name || "Profile"), 100),
          pin: p.pin !== undefined && p.pin !== null ? sanitizeUserInput(String(p.pin), 20) : null,
        })) : (body.profiles === null ? null : undefined);

        const account = await AccountService.updateAccount(id, {
          product_id: prodId && !isNaN(prodId) ? prodId : undefined,
          label: body.label !== undefined ? sanitizeUserInput(String(body.label), 100) : undefined,
          email: body.email,
          password: body.password,
          two_factor_link: body.two_factor_link,
          profiles: sanitizedProfiles,
          status: body.status,
          notes: body.notes !== undefined ? sanitizeUserInput(String(body.notes), 500) : undefined,
        });
        await AuditService.log({ action: "UPDATE_ACCOUNT", entity: "account", entityId: id, details: `Updated account ${id}` });
        sendJson(res, 200, { account: sanitizeAccountForListing(account) }, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }, req));
    return true;
  }

  const accDelMatch = pathname.match(/^\/api\/accounts\/(\d+)$/);
  if (accDelMatch && method === "DELETE") {
    const id = Number(accDelMatch[1]);
    AccountService.deleteAccount(id)
      .then((success) => sendJson(res, 200, { success }, req))
      .catch((err) => sendJson(res, 500, { error: err.message }, req));
    return true;
  }

  // 15. REST API — Customers List
  if (pathname === "/api/customers" && method === "GET") {
    CustomerService.listCustomers()
      .then((customers) => sendJson(res, 200, { customers }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  if (pathname === "/api/customers" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const customer = await CustomerService.createCustomer({
          telegram_id: body.telegramId,
          username: body.username ? sanitizeUserInput(String(body.username), 50) : undefined,
          display_name: body.displayName ? sanitizeUserInput(String(body.displayName), 100) : undefined,
          notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : undefined,
        });
        await AuditService.log({ action: "CREATE_CUSTOMER", entity: "customer", entityId: customer.telegram_id, details: `Added customer ${customer.display_name || customer.username || customer.telegram_id}` });
        sendJson(res, 201, { customer });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  const custDelMatch = pathname.match(/^\/api\/customers\/(\d+)$/);
  if (custDelMatch && method === "DELETE") {
    const id = Number(custDelMatch[1]);
    (async () => {
      if (isCloudFirestore()) {
        const db = getFirestore();
        await db.collection("customers").doc(String(id)).delete();
      } else {
        const pool = getPool();
        await pool.query("DELETE FROM users WHERE telegram_id = $1", [id]);
      }
      await AuditService.log({ action: "DELETE_CUSTOMER", entity: "customer", entityId: id, details: `Deleted customer ${id}` });
      sendJson(res, 200, { success: true });
    })().catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  const custNotesMatch = pathname.match(/^\/api\/customers\/(\d+)\/notes$/);
  if (custNotesMatch && method === "PATCH") {
    const id = Number(custNotesMatch[1]);
    parseBody(req)
      .then(async (body) => {
        const notes = body.notes !== undefined ? sanitizeUserInput(String(body.notes), 500) : "";
        const customer = await CustomerService.updateCustomerNotes(id, notes);
        sendJson(res, 200, { customer });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 16. REST API — Expenses
  if (pathname === "/api/expenses" && method === "GET") {
    ExpenseService.listExpenses()
      .then((expenses) => sendJson(res, 200, { expenses }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  if (pathname === "/api/expenses" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const description = sanitizeUserInput(String(body.description || ""), 250);
        if (!description) {
          return sendJson(res, 400, { error: "Expense description is required" }, req);
        }
        const allowedCategories = ["API Services", "Hosting / Domains", "Other", "Product Purchases", "Telecom"];
        const rawCat = sanitizeUserInput(String(body.category || "Other"), 50);
        const category = allowedCategories.includes(rawCat) ? (rawCat as any) : "Other";
        const expense = await ExpenseService.createExpense({
          category,
          description,
          amount: Number(body.amount),
          date: body.date ? sanitizeUserInput(String(body.date), 50) : undefined,
        });
        await AuditService.log({ action: "CREATE_EXPENSE", entity: "expense", entityId: expense.id, details: `Recorded expense ₱${expense.amount} for ${description}` });
        sendJson(res, 201, { expense });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  const expenseDelMatch = pathname.match(/^\/api\/expenses\/([a-zA-Z0-9_-]+)$/);
  if (expenseDelMatch && method === "DELETE") {
    const id = expenseDelMatch[1];
    ExpenseService.deleteExpense(id)
      .then((success) => sendJson(res, 200, { success }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 17. REST API — Settings
  if (pathname === "/api/settings" && method === "GET") {
    SettingsService.getAllSettings()
      .then((settings) => sendJson(res, 200, { settings }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  if (pathname === "/api/settings" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        for (const [k, v] of Object.entries(body)) {
          if (v !== undefined && v !== null) {
            await SettingsService.setSetting(k, String(v));
          }
        }
        sendJson(res, 200, { success: true });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  // 18. REST API — Test Discord Alert
  if (pathname === "/api/test-discord" && method === "POST") {
    DiscordService.sendTestAlert()
      .then((result) => sendJson(res, 200, result))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 19. REST API — Manual Sync Channel
  if (pathname === "/api/sync-channel" && method === "POST") {
    PublishingService.publishOrRefreshCatalog(bot)
      .then((result) => sendJson(res, 200, result))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 20. REST API — Daily Business Summary Trigger
  if (pathname === "/api/cron/daily-summary" && method === "POST") {
    SummaryService.generateAndSendDailySummary(bot)
      .then((result) => sendJson(res, 200, result))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }


  // 23. REST API — Suppliers & Restock History
  if (pathname === "/api/suppliers" && method === "GET") {
    SupplierService.listSuppliers()
      .then((suppliers) => sendJson(res, 200, { suppliers }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  if (pathname === "/api/suppliers" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const name = sanitizeUserInput(String(body.name || ""), 100);
        if (!name) {
          return sendJson(res, 400, { error: "Supplier name is required" }, req);
        }
        const supplier = await SupplierService.createSupplier(
          name,
          body.contact ? sanitizeUserInput(String(body.contact), 100) : undefined,
          body.notes ? sanitizeUserInput(String(body.notes), 500) : undefined
        );
        await AuditService.log({ action: "CREATE_SUPPLIER", entity: "supplier", entityId: supplier.id, details: `Created supplier ${supplier.name}` });
        sendJson(res, 201, { success: true, supplier });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  if (pathname === "/api/restocks" && method === "GET") {
    SupplierService.listRestockHistory()
      .then((restocks) => sendJson(res, 200, { restocks }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  if (pathname === "/api/restocks" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const supplierName = sanitizeUserInput(String(body.supplierName || ""), 100);
        const productName = sanitizeUserInput(String(body.productName || ""), 100);
        const entry = await SupplierService.recordRestock({
          productId: Number(body.productId),
          productName,
          variantId: body.variantId ? Number(body.variantId) : undefined,
          supplierName,
          quantityAdded: Number(body.quantityAdded),
          totalCost: Number(body.totalCost),
          notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : undefined,
          bot,
        });
        await AuditService.log({ action: "RESTOCK", entity: "product", entityId: body.productId, details: `Restocked +${body.quantityAdded} ${productName} from ${supplierName}` });
        sendJson(res, 201, { success: true, entry });
      })
      .catch((err) => sendJson(res, 400, { error: err.message }));
    return true;
  }

  if (pathname === "/api/stock-adjustments" && method === "GET") {
    SupplierService.listStockAdjustments()
      .then((adjustments) => sendJson(res, 200, { adjustments }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 23b. REST API — Review Supplier Onboarding Application
  if (pathname === "/api/suppliers/review" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const supplierOrgId = String(body.supplierOrgId || "").trim();
        const decision = body.decision === "REJECT" ? "REJECT" : "APPROVE";
        if (!supplierOrgId) {
          return sendJson(res, 400, { error: "supplierOrgId is required" }, req);
        }
        const { reviewSupplierOnboardingApplication } = await import("@/src/admin/admin.service");
        const result = await reviewSupplierOnboardingApplication(
          { isInternalAdmin: true, user: { role: "super_admin" } } as any,
          {
            supplierOrgId,
            decision,
            commissionRateBps: body.commissionRateBps !== undefined ? Number(body.commissionRateBps) : undefined,
            notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : undefined,
          }
        );
        await AuditService.log({
          action: "REVIEW_SUPPLIER",
          entity: "supplier",
          entityId: supplierOrgId,
          details: `Supplier application ${decision.toLowerCase()}d for org ${supplierOrgId}`,
        });
        sendJson(res, 200, result, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }, req));
    return true;
  }

  // 23c. REST API — Credit Reseller Wallet
  if (pathname === "/api/resellers/credit" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        const resellerId = String(body.resellerOrgId || body.resellerId || "").trim();
        const amount = Number(body.amount);
        if (!resellerId || isNaN(amount) || amount <= 0) {
          return sendJson(res, 400, { error: "Valid resellerOrgId and positive amount are required" }, req);
        }
        const { creditResellerWallet } = await import("@/src/admin/admin.service");
        const result = await creditResellerWallet(
          { isInternalAdmin: true, user: { role: "super_admin" } } as any,
          {
            resellerId,
            amount,
            referenceId: String(body.referenceId || ("admin-credit-" + Date.now())),
            notes: body.notes ? sanitizeUserInput(String(body.notes), 500) : "Manual admin credit",
          }
        );
        await AuditService.log({
          action: "CREDIT_RESELLER",
          entity: "reseller",
          entityId: resellerId,
          details: `Credited ₱${amount.toFixed(2)} to reseller org ${resellerId}`,
        });
        sendJson(res, 200, { success: true, ...result }, req);
      })
      .catch((err) => sendJson(res, 400, { error: err.message }, req));
    return true;
  }

  // 24. REST API — Audit Logs
  if (pathname === "/api/audit-logs" && method === "GET") {
    AuditService.list()
      .then((logs) => sendJson(res, 200, { logs }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 25. REST API — Demand & Restock Waitlist Notification
  if (pathname === "/api/demand" && method === "GET") {
    (async () => {
      let requests: any[] = [];
      let waitlists: any[] = [];
      if (isCloudFirestore()) {
        const db = getFirestore();
        const reqSnap = await db.collection("product_requests").orderBy("created_at", "desc").limit(50).get();
        requests = reqSnap.docs.map((d) => ({ id: d.id, ...d.data() }));

        const waitSnap = await db.collection("waitlist").orderBy("created_at", "desc").limit(100).get();
        waitlists = waitSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      }
      sendJson(res, 200, { requests, waitlists });
    })().catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  const notifyWaitlistMatch = pathname.match(/^\/api\/waitlist\/(\d+)\/notify$/);
  if (notifyWaitlistMatch && method === "POST") {
    const productId = Number(notifyWaitlistMatch[1]);
    (async () => {
      if (isCloudFirestore()) {
        const db = getFirestore();
        const prodDoc = await db.collection("products").doc(String(productId)).get();
        const prodData = prodDoc.data() || {};
        const pName = prodData.name || "Product";

        const waitSnap = await db.collection("waitlist").where("product_id", "==", productId).where("status", "==", "WAITING").get();
        let notifiedCount = 0;

        for (const doc of waitSnap.docs) {
          const wData = doc.data();
          try {
            await bot.api.sendMessage(
              wData.customer_id,
              `🎉 <b>GOOD NEWS! BACK IN STOCK!</b>\n\n<b>${pName}</b> is now available! Order now before slots run out:`,
              {
                parse_mode: "HTML",
                reply_markup: {
                  inline_keyboard: [[{ text: "🛒 Order " + pName, callback_data: `customer:order:${productId}` }]],
                },
              }
            );
            await doc.ref.update({ status: "NOTIFIED", notified_at: new Date().toISOString() });
            notifiedCount++;
          } catch {}
        }
        sendJson(res, 200, { success: true, notifiedCount });
      } else {
        sendJson(res, 200, { success: true, notifiedCount: 0 });
      }
    })().catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 26. REST API — Customer Expiration Reminders Trigger
  if (pathname === "/api/cron/expiration-reminders" && method === "POST") {
    SummaryService.sendCustomerExpirationReminders(bot)
      .then((result) => sendJson(res, 200, { success: true, ...result }))
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  // 27. REST API — Danger Zone: Clear Test Orders
  if (pathname === "/api/danger/clear-test-orders" && method === "POST") {
    parseBody(req)
      .then(async (body) => {
        if (body.confirmation !== "CONFIRM_DELETE_TEST_ORDERS") {
          sendJson(res, 400, { error: "Incorrect confirmation string. Must type CONFIRM_DELETE_TEST_ORDERS" });
          return;
        }

        if (isCloudFirestore()) {
          const db = getFirestore();
          const snap = await db.collection("orders").where("state", "in", ["DRAFT", "CANCELLED", "REJECTED"]).get();
          const batch = db.batch();
          snap.forEach((d) => batch.delete(d.ref));
          await batch.commit();
          sendJson(res, 200, { success: true, deletedCount: snap.size });
        } else {
          const pool = getPool();
          const { rowCount } = await pool.query("DELETE FROM orders WHERE state IN ('DRAFT', 'CANCELLED', 'REJECTED')");
          sendJson(res, 200, { success: true, deletedCount: rowCount });
        }
      })
      .catch((err) => sendJson(res, 500, { error: err.message }));
    return true;
  }

  return false;
}

/**
 * LIGHT E-INK PAPER DEVELOPER DASHBOARD HTML.
 */
export function getDashboardHtml(): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>XEURIE | Deployments & Commerce Console</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg-paper: #f4f1ea;
      --bg-raised: #faf8f3;
      --ink-primary: #141310;
      --ink-secondary: rgba(20, 19, 16, 0.62);
      --ink-muted: rgba(20, 19, 16, 0.42);
      --border-hairline: rgba(20, 19, 16, 0.14);
      --signal-red: #c8321e;
      --radius-sm: 3px;
      --radius-md: 5px;
      --radius-lg: 8px;
      --font-sans: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      --font-mono: 'IBM Plex Mono', monospace;
    }

    [data-theme="dark"] {
      --bg-paper: #0b0f19;
      --bg-raised: #111827;
      --ink-primary: #f8fafc;
      --ink-secondary: rgba(248, 250, 252, 0.65);
      --ink-muted: rgba(248, 250, 252, 0.4);
      --border-hairline: rgba(248, 250, 252, 0.12);
      --signal-red: #f87171;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background-color: var(--bg-paper);
      color: var(--ink-primary);
      font-family: var(--font-sans);
      font-size: 13px;
      line-height: 1.45;
      min-height: 100vh;
      -webkit-font-smoothing: antialiased;
    }

    .mono-nums {
      font-family: var(--font-mono);
      font-variant-numeric: tabular-nums;
    }

    /* Two-pane App Shell */
    .app-shell {
      display: flex;
      min-height: 100vh;
    }

    /* Fixed Left Sidebar */
    .sidebar {
      width: 240px;
      background-color: var(--bg-raised);
      border-right: 1px solid var(--border-hairline);
      display: flex;
      flex-direction: column;
      flex-shrink: 0;
    }

    .sidebar-header {
      padding: 16px 14px;
      border-bottom: 1px solid var(--border-hairline);
    }

    .workspace-switcher {
      display: flex;
      align-items: center;
      gap: 10px;
      cursor: pointer;
    }

    .workspace-glyph {
      width: 26px;
      height: 26px;
      border: 1px solid var(--ink-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-mono);
      font-weight: 600;
      font-size: 11px;
    }

    .workspace-meta {
      flex: 1;
      min-width: 0;
    }

    .workspace-name {
      font-weight: 600;
      font-size: 12.5px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .workspace-sub {
      font-size: 10.5px;
      color: var(--ink-muted);
    }

    .sidebar-search {
      padding: 12px 14px;
      border-bottom: 1px solid var(--border-hairline);
    }

    .search-box {
      display: flex;
      align-items: center;
      gap: 8px;
      background: var(--bg-paper);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-sm);
      padding: 5px 8px;
    }

    .search-box input {
      background: transparent;
      border: none;
      outline: none;
      font-family: var(--font-sans);
      font-size: 12px;
      color: var(--ink-primary);
      width: 100%;
    }

    .search-box input::placeholder {
      color: var(--ink-muted);
    }

    .kbd-chip {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--ink-muted);
      border: 1px solid var(--border-hairline);
      padding: 1px 4px;
      border-radius: 2px;
    }

    .nav-section-title {
      font-size: 10.5px;
      font-weight: 600;
      letter-spacing: 0.08em;
      color: var(--ink-muted);
      text-transform: uppercase;
      padding: 16px 14px 6px;
    }

    .nav-list {
      display: flex;
      flex-direction: column;
      gap: 1px;
    }

    .nav-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 14px;
      font-size: 12.5px;
      color: var(--ink-secondary);
      background: transparent;
      border: none;
      width: 100%;
      text-align: left;
      cursor: pointer;
      font-family: var(--font-sans);
      border-left: 3px solid transparent;
    }

    .nav-item:hover {
      color: var(--ink-primary);
      background: rgba(20, 19, 16, 0.03);
    }

    .nav-item.active {
      color: var(--ink-primary);
      font-weight: 600;
      background: var(--bg-paper);
      border-left-color: var(--ink-primary);
    }

    .nav-counter {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--ink-muted);
    }

    .env-list {
      padding: 0 14px;
      display: flex;
      flex-direction: column;
      gap: 7px;
    }

    .env-row {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--ink-secondary);
    }

    /* Ink Semantic Glyphs */
    .ink-glyph {
      font-family: var(--font-mono);
      font-size: 11px;
      display: inline-block;
      width: 12px;
      text-align: center;
    }
    .ink-glyph.ready { color: var(--ink-primary); }
    .ink-glyph.building { color: var(--ink-primary); }
    .ink-glyph.queued { color: var(--ink-muted); }
    .ink-glyph.failed { color: var(--signal-red); font-weight: 700; }

    .sidebar-bottom {
      margin-top: auto;
      padding: 14px;
      border-top: 1px solid var(--border-hairline);
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .usage-card {
      background: var(--bg-paper);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-sm);
      padding: 10px;
    }

    .usage-header {
      display: flex;
      justify-content: space-between;
      font-size: 11px;
      margin-bottom: 6px;
      color: var(--ink-secondary);
    }

    .usage-track {
      width: 100%;
      height: 4px;
      background: rgba(20, 19, 16, 0.1);
      border-radius: 2px;
      overflow: hidden;
    }

    .usage-fill {
      height: 100%;
      background: var(--ink-primary);
    }

    .user-row {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .user-chip {
      width: 26px;
      height: 26px;
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-mono);
      font-size: 10.5px;
      font-weight: 600;
      background: var(--bg-paper);
    }

    .user-info {
      line-height: 1.25;
    }

    .user-name {
      font-size: 12px;
      font-weight: 600;
    }

    .user-handle {
      font-size: 10.5px;
      color: var(--ink-muted);
    }

    /* Main Content Column */
    .main-column {
      flex: 1;
      display: flex;
      flex-direction: column;
      min-width: 0;
    }

    /* Top Header Bar */
    .header-bar {
      height: 52px;
      background: var(--bg-raised);
      border-bottom: 1px solid var(--border-hairline);
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .breadcrumb {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12.5px;
      color: var(--ink-muted);
    }

    .breadcrumb-current {
      color: var(--ink-primary);
      font-weight: 600;
    }

    /* Segmented Control */
    .segmented-control {
      display: inline-flex;
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-sm);
      overflow: hidden;
      background: var(--bg-paper);
    }

    .seg-btn {
      padding: 4px 12px;
      font-family: var(--font-sans);
      font-size: 11.5px;
      background: transparent;
      border: none;
      border-right: 1px solid var(--border-hairline);
      cursor: pointer;
      color: var(--ink-secondary);
    }

    .seg-btn:last-child { border-right: none; }

    .seg-btn.active {
      background: var(--ink-primary);
      color: var(--bg-paper);
      font-weight: 500;
    }

    /* Actions */
    .header-actions {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn {
      font-family: var(--font-sans);
      font-size: 12px;
      font-weight: 500;
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      border: 1px solid transparent;
      text-decoration: none;
    }

    .btn-primary {
      background: var(--ink-primary);
      color: var(--bg-paper);
      border-color: var(--ink-primary);
    }

    .btn-secondary {
      background: transparent;
      border-color: var(--border-hairline);
      color: var(--ink-primary);
    }

    .btn-secondary:hover {
      background: rgba(20, 19, 16, 0.04);
    }

    .btn-ghost {
      background: transparent;
      color: var(--ink-secondary);
    }

    .btn-ghost:hover {
      color: var(--ink-primary);
      background: rgba(20, 19, 16, 0.04);
    }

    .btn-sm {
      padding: 3px 8px;
      font-size: 11px;
    }

    .btn-danger {
      border-color: var(--signal-red);
      color: var(--signal-red);
      background: transparent;
    }

    .btn-danger:hover {
      background: rgba(200, 50, 30, 0.08);
    }

    .btn:active:not(:disabled) {
      transform: scale(0.98);
    }

    /* Content Body */
    .content-body {
      padding: 24px;
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    /* Cards */
    .card {
      background: var(--bg-raised);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-md);
      overflow: hidden;
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), inset 0 -1px 0 rgba(0, 0, 0, 0.08);
    }

    .card-header {
      padding: 14px 18px;
      border-bottom: 1px solid var(--border-hairline);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .card-title {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .card-body {
      padding: 18px;
    }

    /* Hero Card with Dot-Grain Texture */
    .hero-card {
      background-color: var(--bg-raised);
      background-image: radial-gradient(rgba(20, 19, 16, 0.06) 0.5px, transparent 0.5px);
      background-size: 4px 4px;
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-md);
      padding: 18px 20px;
      display: flex;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
    }

    .hero-left {
      display: flex;
      flex-direction: column;
      gap: 6px;
      min-width: 280px;
    }

    .hero-status-row {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      font-weight: 600;
    }

    .hero-domain {
      font-family: var(--font-mono);
      font-size: 12px;
      color: var(--ink-primary);
      text-decoration: underline;
    }

    .hero-commit-chip {
      display: inline-flex;
      align-items: center;
      font-family: var(--font-mono);
      font-size: 11px;
      border: 1px solid var(--border-hairline);
      padding: 2px 6px;
      border-radius: var(--radius-sm);
      background: var(--bg-paper);
      margin-top: 4px;
      width: fit-content;
    }

    .hero-meta {
      font-size: 11px;
      color: var(--ink-muted);
      margin-top: 4px;
    }

    /* 4-Stage Pipeline Strip */
    .pipeline-container {
      display: flex;
      flex-direction: column;
      justify-content: center;
      min-width: 320px;
      gap: 8px;
    }

    .pipeline-strip {
      position: relative;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      padding-top: 6px;
    }

    .pipeline-rail {
      position: absolute;
      top: 12px;
      left: 10px;
      right: 10px;
      height: 1px;
      background: var(--border-hairline);
      z-index: 1;
    }

    .pipeline-stage {
      position: relative;
      z-index: 2;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 4px;
    }

    .stage-dot {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--ink-primary);
      outline: 4px solid var(--bg-raised);
    }

    .stage-name {
      font-size: 10px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-secondary);
    }

    .stage-duration {
      font-family: var(--font-mono);
      font-size: 10.5px;
      color: var(--ink-muted);
    }

    .pipeline-caption {
      font-size: 11px;
      color: var(--ink-muted);
      text-align: right;
    }

    /* KPI Grid */
    .kpi-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 14px;
    }

    .kpi-card {
      background: var(--bg-raised);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-md);
      padding: 14px 16px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .kpi-label {
      font-size: 10.5px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
    }

    .kpi-value {
      font-family: var(--font-mono);
      font-size: 20px;
      font-weight: 600;
      color: var(--ink-primary);
    }

    .kpi-sub {
      font-size: 11px;
      color: var(--ink-secondary);
    }

    /* Data Tables */
    .table-container {
      width: 100%;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 12.5px;
      text-align: left;
    }

    th {
      font-size: 10.5px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
      padding: 10px 14px;
      border-bottom: 1px solid var(--border-hairline);
      background: rgba(20, 19, 16, 0.02);
    }

    td {
      padding: 10px 14px;
      border-bottom: 1px solid var(--border-hairline);
      color: var(--ink-primary);
      vertical-align: middle;
    }

    tr:last-child td {
      border-bottom: none;
    }

    tr.row-failed td {
      color: var(--signal-red);
    }

    .cell-code {
      font-family: var(--font-mono);
      font-size: 12px;
    }

    .chip {
      font-family: var(--font-mono);
      font-size: 11px;
      padding: 2px 6px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-hairline);
      background: var(--bg-paper);
      display: inline-block;
    }

    /* Bottom Split Row */
    .split-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    @media (max-width: 960px) {
      .split-row { grid-template-columns: 1fr; }
      .sidebar { width: 100%; border-right: none; border-bottom: 1px solid var(--border-hairline); }
      .app-shell { flex-direction: column; }
    }

    /* Build Log Card */
    .log-block {
      background: var(--bg-paper);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-sm);
      padding: 12px 14px;
      font-family: var(--font-mono);
      font-size: 11.5px;
      line-height: 1.6;
      overflow-x: auto;
      max-height: 190px;
    }

    .log-line {
      white-space: nowrap;
      color: var(--ink-secondary);
    }

    .log-line.log-error {
      color: var(--signal-red);
      font-weight: 500;
    }

    /* Stepped Bar Chart */
    .chart-container {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .bar-chart {
      display: flex;
      align-items: flex-end;
      gap: 6px;
      height: 110px;
      padding-bottom: 6px;
      border-bottom: 1px solid var(--border-hairline);
    }

    .bar-col {
      flex: 1;
      height: 100%;
      display: flex;
      align-items: flex-end;
    }

    .bar-fill {
      width: 100%;
      background: var(--ink-primary);
      border-radius: 1px 1px 0 0;
      min-height: 4px;
    }

    .chart-labels {
      display: flex;
      justify-content: space-between;
      font-size: 10.5px;
      color: var(--ink-muted);
    }

    .chart-stats {
      font-family: var(--font-mono);
      font-size: 11.5px;
      color: var(--ink-primary);
      margin-top: 4px;
    }

    /* Modals */
    .modal {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(20, 19, 16, 0.55);
      backdrop-filter: blur(2px);
      -webkit-backdrop-filter: blur(2px);
      z-index: 1000;
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      padding: 20px 14px;
      box-sizing: border-box;
    }

    .modal-content {
      background: var(--bg-raised);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-md);
      padding: 22px 24px;
      width: 100%;
      max-width: 520px;
      max-height: calc(100vh - 40px);
      display: flex;
      flex-direction: column;
      margin: auto;
      box-shadow: 0 16px 40px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.08), inset 0 -1px 0 rgba(0, 0, 0, 0.1);
      position: relative;
      box-sizing: border-box;
      overflow-y: auto;
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
    }

    .modal-content.has-body,
    .modal-content:has(.modal-body) {
      overflow: hidden;
      padding: 20px 24px 16px 24px;
    }

    .modal-header {
      flex-shrink: 0;
      margin-bottom: 14px;
      padding-bottom: 10px;
      border-bottom: 1px solid var(--border-hairline);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .modal-body {
      flex: 1 1 auto;
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      padding-right: 6px;
      min-height: 0;
    }

    .modal-footer {
      flex-shrink: 0;
      display: flex;
      justify-content: flex-end;
      gap: 8px;
      border-top: 1px solid var(--border-hairline);
      padding-top: 14px;
      margin-top: 14px;
    }

    @media (max-width: 600px) {
      .modal {
        padding: 10px 8px;
      }
      .modal-content {
        padding: 16px 14px;
        max-height: calc(100vh - 20px);
      }
      .modal-content.has-body,
      .modal-content:has(.modal-body) {
        padding: 14px 14px 12px 14px;
      }
    }

    .form-group {
      margin-bottom: 14px;
    }

    .form-group label {
      display: block;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
      margin-bottom: 4px;
    }

    .form-control {
      width: 100%;
      background: var(--bg-paper);
      border: 1px solid var(--border-hairline);
      border-radius: var(--radius-sm);
      padding: 7px 10px;
      font-family: var(--font-sans);
      font-size: 12.5px;
      color: var(--ink-primary);
      outline: none;
    }

    .form-control:focus {
      border-color: var(--ink-primary);
    }
  </style>
</head>
<body>

  <!-- Owner Login Overlay -->
  <div id="loginOverlay" style="display: none; position: fixed; inset: 0; background: var(--bg-paper); z-index: 9999; align-items: center; justify-content: center;">
    <div class="modal-content" style="text-align: center; width: 340px;">
      <div class="workspace-glyph" style="margin: 0 auto 12px; width: 34px; height: 34px; font-size: 14px;">SD</div>
      <h2 style="font-size: 15px; font-weight: 600; margin-bottom: 4px;">XEURIE Owner Console</h2>
      <p style="font-size: 11.5px; color: var(--ink-muted); margin-bottom: 16px;">Enter Owner PIN / Password to unlock:</p>
      <input id="login-pin" type="password" class="form-control mono-nums" placeholder="••••••••" style="text-align: center; font-size: 15px; letter-spacing: 3px; margin-bottom: 14px;" onkeydown="if(event.key==='Enter') performLogin()">
      <button class="btn btn-primary" style="width: 100%; justify-content: center;" onclick="performLogin()">Unlock Console</button>
    </div>
  </div>

  <div class="app-shell">
    <!-- Fixed Left Sidebar -->
    <aside class="sidebar">
      <div class="sidebar-header">
        <div class="workspace-switcher">
          <div class="workspace-glyph">SD</div>
          <div class="workspace-info">
            <div class="workspace-name">XEURIE Commerce</div>
            <div class="workspace-sub">Superdesign Space</div>
          </div>
          <div style="color: var(--ink-muted);">▾</div>
        </div>
      </div>

      <div class="sidebar-search">
        <div class="search-box">
          <span>🔍</span>
          <input id="global-search" placeholder="Search..." oninput="handleSearch(this.value)">
          <kbd class="kbd-chip">⌘K</kbd>
        </div>
      </div>

      <div class="nav-section-title">NAVIGATION</div>
      <nav class="nav-list">
        <button class="nav-item active" onclick="showTab('overview', this)">
          <span>📊 Overview</span>
        </button>
        <button class="nav-item" onclick="showTab('products', this)">
          <span>📦 Products & Pricing</span>
        </button>
        <button class="nav-item" onclick="showTab('orders', this)">
          <span>📋 Deployments / Orders</span>
          <span id="badge-orders-nav" class="nav-counter">0</span>
        </button>
        <button class="nav-item" onclick="showTab('subscriptions', this)">
          <span>📅 Subscriptions</span>
          <span id="badge-subs-nav" class="nav-counter">0</span>
