          '</div>';
        }

        // 2FA Link display
        let twoFaDisplay = '<span style="color:var(--ink-muted);font-size:11px;font-style:italic;">None</span>';
        if (a.has_2fa || a.two_factor_link) {
          twoFaDisplay = '<div style="display:flex;align-items:center;gap:4px;white-space:nowrap;">' +
            '<button class="btn btn-secondary btn-sm" style="padding:2px 7px;font-size:10.5px;color:#1a73e8;font-weight:600;white-space:nowrap;flex-shrink:0;" title="Open 2FA link" onclick="openAccount2FA(' + a.id + ')">🔗 Open 2FA</button>' +
            '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;white-space:nowrap;flex-shrink:0;" title="Copy 2FA Link/Key" onclick="copyAccount2FA(' + a.id + ')">📋</button>' +
          '</div>';
        }

        return '<tr>' +
          '<td style="white-space:nowrap;">' + emailDisplay + '</td>' +
          '<td style="white-space:nowrap;">' + pwdDisplay + '</td>' +
          '<td>' + profDisplay + '</td>' +
          '<td style="white-space:nowrap;">' + twoFaDisplay + '</td>' +
          '<td style="white-space:nowrap;">' +
            '<div style="display:flex;align-items:center;gap:6px;">' +
              '<strong>' + escapeHtml(a.product_name || 'Product') + '</strong>' +
              '<button class="btn btn-secondary btn-sm" style="padding:1px 5px;font-size:10px;line-height:1;" title="Edit Product / Account" onclick="openEditAccountModal(' + a.id + ')">✏️</button>' +
            '</div>' +
          '</td>' +
          '<td style="white-space:nowrap;">' + statusBadge + '</td>' +
          '<td style="white-space:nowrap;">' + (a.current_customer_username ? '@' + escapeHtml(a.current_customer_username) : (a.current_customer_id ? '<span class="mono-nums">ID: ' + escapeHtml(a.current_customer_id) + '</span>' : '<span style="color:var(--ink-muted);">-</span>')) + '</td>' +
          '<td>' + (a.notes ? escapeHtml(a.notes) : '<span style="color:var(--ink-muted);">-</span>') + '</td>' +
          '<td style="white-space:nowrap;">' +
            '<div style="display:flex;gap:4px;white-space:nowrap;">' +
              '<button class="btn btn-secondary btn-sm" title="Toggle Status" onclick="toggleAccStatus(' + Number(a.id) + ')">Toggle</button>' +
              '<button class="btn btn-secondary btn-sm" title="Copy Full Credentials Info" onclick="copyFullAccountInfo(' + Number(a.id) + ')">📋 Info</button>' +
              '<button class="btn btn-secondary btn-sm" title="Edit Credentials" onclick="openEditAccountModal(' + Number(a.id) + ')">✏️</button>' +
              '<button class="btn btn-danger btn-sm" title="Delete Account" onclick="deleteAccount(' + Number(a.id) + ')">🗑️</button>' +
            '</div>' +
          '</td>' +
        '</tr>';
      }).join('');
    }

