      if (!Array.isArray(suppliers) || suppliers.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--ink-muted); padding: 24px;">No supplier records registered. Add a supplier source above or await onboarding applications.</td></tr>';
        return;
