      tbody.innerHTML = suppliers.map(s => {
        const statusBadge = (s.status === 'PENDING_VERIFICATION' || !s.is_verified)
          ? '<span class="chip" style="background:#fef3c7; color:#92400e; font-weight:600;">PENDING</span>'
          : '<span class="chip" style="background:#dcfce7; color:#166534; font-weight:600;">ACTIVE</span>';

        const actionBtns = (s.status === 'PENDING_VERIFICATION' || !s.is_verified)
          ? '<button class="btn btn-primary btn-sm" data-supplier-id="' + escapeHtml(s.id) + '" data-action="APPROVE" onclick="handleSupplierReviewBtn(this)">Approve</button> ' +
