    function renderResellers(resellers) {
      const tbody = document.getElementById('resellers-tbody');
      if (!tbody) return;
      if (!Array.isArray(resellers) || resellers.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--ink-muted); padding: 24px;">No reseller partners registered. New reseller organizations will appear here upon signup.</td></tr>';
        return;
      }
      tbody.innerHTML = resellers.map(r => {
        const tierName = (r.tier || 'standard').toUpperCase();
        const tierChip = '<span class="chip">' + escapeHtml(tierName) + '</span>';
        const balance = Number(r.credit_balance || 0).toFixed(2);
        const markup = (r.markup_percentage !== undefined && r.markup_percentage !== null) ? (Number(r.markup_percentage).toFixed(1) + '%') : '0.0%';
        const statusBadge = (r.status === 'SUSPENDED')
          ? '<span class="chip" style="background:#fee2e2; color:#991b1b; font-weight:600;">SUSPENDED</span>'
          : '<span class="chip" style="background:#dcfce7; color:#166534; font-weight:600;">ACTIVE</span>';

