    function handleSupplierReviewBtn(btn) {
      if (!btn) return;
      const orgId = btn.getAttribute('data-supplier-id');
      const action = btn.getAttribute('data-action');
      reviewSupplier(orgId, action);
    }

    function handleCreditResellerBtn(btn) {
      if (!btn) return;
      const orgId = btn.getAttribute('data-reseller-id');
      openCreditWalletModal(orgId);
    }

    async function reviewSupplier(orgId, decision) {
      if (!confirm('Are you sure you want to ' + decision.toLowerCase() + ' this supplier application?')) return;
      try {
        const res = await fetch('/api/suppliers/review', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ supplierOrgId: orgId, decision })
        }).then(r => r.json());
        if (res.success) {
          alert('Supplier application ' + decision.toLowerCase() + 'd successfully.');
          loadAll();
        } else {
          alert('Error: ' + (res.error || 'Failed to review supplier'));
        }
      } catch (err) {
        alert('Network error: ' + err.message);
      }
    }

    function openCreditWalletModal(selectedOrgId) {
      const select = document.getElementById('credit-reseller-select');
      if (select) {
        select.innerHTML = '<option value="">Select Reseller Partner...</option>' +
          (globalData.resellers || []).map(r => '<option value="' + escapeHtml(r.id) + '"' + (r.id === selectedOrgId ? ' selected' : '') + '>' + escapeHtml(r.name || r.display_name || r.id) + ' (Balance: ₱' + Number(r.credit_balance || 0).toFixed(2) + ')</option>').join('');
      }
      openModal('creditWalletModal');
    }

    async function submitWalletCredit() {
      const select = document.getElementById('credit-reseller-select');
      const amountInput = document.getElementById('credit-amount');
      const notesInput = document.getElementById('credit-notes');

      const resellerOrgId = select ? select.value : '';
      const amount = amountInput ? Number(amountInput.value) : 0;
      const notes = notesInput ? notesInput.value.trim() : '';

      if (!resellerOrgId) { alert('Please select a reseller partner.'); return; }
      if (!amount || amount <= 0) { alert('Please enter a valid credit amount.'); return; }

      try {
        const res = await fetch('/api/resellers/credit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ resellerOrgId, amount, notes })
        }).then(r => r.json());

        if (res.success) {
          alert('Wallet credited successfully (+₱' + amount.toFixed(2) + ').');
          closeModal('creditWalletModal');
          if (amountInput) amountInput.value = '';
          if (notesInput) notesInput.value = '';
          loadAll();
        } else {
          alert('Error: ' + (res.error || 'Failed to credit wallet'));
        }
      } catch (err) {
        alert('Network error: ' + err.message);
      }
    }

    function handleSearch(term) {
      const t = term.toLowerCase().trim();
      if (!t) {
        renderProducts(globalData.products);
        renderOrders(globalData.orders);
        renderCustomers(globalData.customers);
        return;
      }
      renderProducts(globalData.products.filter(p => (p.name && p.name.toLowerCase().includes(t)) || (p.category && p.category.toLowerCase().includes(t))));
      renderOrders(globalData.orders.filter(o => (o.code && o.code.toLowerCase().includes(t)) || (o.customer_username && o.customer_username.toLowerCase().includes(t))));
      renderCustomers(globalData.customers.filter(c => (c.username && c.username.toLowerCase().includes(t)) || (c.display_name && c.display_name.toLowerCase().includes(t))));
    }

