    async function copyFullAccountInfo(id) {
      const a = (globalData.accounts || []).find(x => x.id === id);
      if (!a) return;

      let creds = a;
      const needsFetch = (a.has_password && !a.password) ||
                         (a.has_2fa && !a.two_factor_link) ||
                         (Array.isArray(a.profiles) && a.profiles.some(p => p.has_pin && (!p.pin || p.pin === '••••')));
      if (needsFetch) {
        try {
          creds = await fetchAccountCredentials(id);
        } catch (err) {
          alert('Could not retrieve full credentials: ' + err.message);
          return;
        }
      }

      const lines = [];
      if (a.product_name) lines.push('Service: ' + a.product_name);
      const emailVal = creds.email || a.email || a.label;
      if (emailVal) lines.push('Email/User: ' + emailVal);
      if (creds.password) lines.push('Password: ' + creds.password);
      if (Array.isArray(creds.profiles) && creds.profiles.length > 0) {
        lines.push('Profiles:');
        creds.profiles.forEach(p => {
          lines.push('  • ' + p.name + (p.pin ? ' (PIN: ' + p.pin + ')' : ''));
        });
      }
      if (creds.two_factor_link) lines.push('2FA Link/Key: ' + creds.two_factor_link);
      if (a.notes) lines.push('Notes: ' + a.notes);
      copyToClipboard(lines.join(String.fromCharCode(10)));
    }

